const HSK2_DATA = {"lessons": [{"id": 1, "title_cn": "她请我们吃了北京烤鸭", "title_pinyin": "Tā qǐng wǒmen chīle Běijīng Kǎoyā", "title_vn": "Chị ấy đã mời chúng em ăn vịt quay Bắc Kinh", "goals": ["Có thể nghe hiểu và sử dụng được \"请\", \"让\" và \"叫\" để bày tỏ yêu cầu hoặc thỉnh cầu.", "Nắm vững cách dùng của trợ từ ngữ khí \"吧\" (2) để diễn đạt ngữ khí suy đoán hoặc ước tính.", "Nắm vững câu \"是……的\" để nhấn mạnh các thông tin như thời gian, địa điểm và cách thức tiến hành của sự việc.", "Hiểu về vịt quay Bắc Kinh và cách thưởng thức món ăn này."], "vocab": [{"hanzi": "就", "pinyin": "jiù", "pos": "phó.", "vn": "chính (là), thì"}, {"hanzi": "给", "pinyin": "gěi", "pos": "giới.", "vn": "cho"}, {"hanzi": "让", "pinyin": "ràng", "pos": "dgt.", "vn": "bảo, để, cho phép, nhờ"}, {"hanzi": "接", "pinyin": "jiē", "pos": "dgt.", "vn": "đón"}, {"hanzi": "次", "pinyin": "cì", "pos": "lượng.", "vn": "lần"}, {"hanzi": "旅游", "pinyin": "lǚyóu", "pos": "dgt.", "vn": "du lịch"}, {"hanzi": "帮忙", "pinyin": "bāngmáng", "pos": "dgt.", "vn": "giúp đỡ"}, {"hanzi": "不好意思", "pinyin": "bù hǎoyìsi", "pos": "", "vn": "xin lỗi, áy náy, ngại"}, {"hanzi": "已经", "pinyin": "yǐjīng", "pos": "phó.", "vn": "đã"}, {"hanzi": "那", "pinyin": "nà", "pos": "liên.", "vn": "vậy, vậy thì, thế thì"}, {"hanzi": "介绍", "pinyin": "jièshào", "pos": "dgt.", "vn": "giới thiệu"}, {"hanzi": "有时", "pinyin": "yǒushí", "pos": "phó.", "vn": "có lúc, có khi"}, {"hanzi": "懂", "pinyin": "dǒng", "pos": "dgt.", "vn": "hiểu"}, {"hanzi": "意思", "pinyin": "yìsi", "pos": "dt.", "vn": "ý, ý nghĩa"}, {"hanzi": "北京烤鸭", "pinyin": "Běijīng Kǎoyā", "pos": "danh từ riêng", "vn": "vịt quay Bắc Kinh"}], "grammar": [{"title": "语气助词“吧”(2)", "explanation_vn": "Trợ từ ngữ khí \"吧\" đặt cuối câu nghi vấn để diễn đạt ngữ khí suy đoán hoặc ước tính.", "examples": [{"cn": "你们就是她的学生吧？", "pinyin": "Nǐmen jiù shì tā de xuésheng ba?", "vn": ""}, {"cn": "她唱歌很好听吧？", "pinyin": "Tā chànggē hěn hǎotīng ba?", "vn": ""}, {"cn": "陈天中是泰国人吧？", "pinyin": "Chén Tiānzhōng shì Tàiguó rén ba?", "vn": ""}]}, {"title": "“是……的”句", "explanation_vn": "Câu \"是……的\" dùng để nhấn mạnh thời gian, địa điểm, cách thức, người thực hiện động tác, mục đích... của sự việc. Trong câu khẳng định và câu nghi vấn có thể lược bỏ \"是\", trong câu phủ định không được lược bỏ \"是\".", "examples": [{"cn": "我们是来旅游的。", "pinyin": "Wǒmen shì lái lǚyóu de.", "vn": ""}, {"cn": "苹果在哪儿买的？", "pinyin": "Píngguǒ zài nǎr mǎi de?", "vn": ""}, {"cn": "我们不是坐出租车去的。", "pinyin": "Wǒmen bú shì zuò chūzūchē qù de.", "vn": ""}]}, {"title": "兼语句", "explanation_vn": "Vị ngữ của câu kiêm ngữ được tạo thành bởi hai cụm động từ, trong đó tân ngữ của động từ thứ nhất là chủ ngữ của động từ thứ hai. Khi động từ thứ nhất là \"请\", \"让\", \"叫\", dùng để biểu thị ý mời, phiền, nhờ, cho phép, yêu cầu, sai bảo... ai đó làm gì. Cấu trúc cơ bản: Chủ ngữ + 请/让/叫 + tân ngữ (→ chủ ngữ) + động từ hoặc cụm động từ.", "examples": [{"cn": "我想请你帮个忙。", "pinyin": "Wǒ xiǎng qǐng nǐ bāng ge máng.", "vn": ""}, {"cn": "王老师让我们说中文。", "pinyin": "Wáng lǎoshī ràng wǒmen shuō Zhōngwén.", "vn": ""}, {"cn": "妈妈叫孩子们回家。", "pinyin": "Māma jiào háizimen huí jiā.", "vn": ""}]}], "texts": [{"label": "Bài khóa 1", "type": "dialogue", "lines": [{"speaker": "白家月", "cn": "请问，您是王一飞老师的姐姐吗？", "pinyin": "Qǐngwèn, nín shì Wáng Yīfēi lǎoshī de jiějie ma?"}, {"speaker": "王一雪", "cn": "是的，你们就是她的学生吧？", "pinyin": "Shì de, nǐmen jiù shì tā de xuésheng ba?"}, {"speaker": "白家月", "cn": "对。我是白家月，她是安妮。", "pinyin": "Duì. Wǒ shì Bái Jiāyuè, tā shì Ānní."}, {"speaker": "王一雪", "cn": "你们好，我叫王一雪。一飞给我打电话了，让我来接你们。", "pinyin": "Nǐmen hǎo, wǒ jiào Wáng Yīxuě. Yīfēi gěi wǒ dǎ diànhuà le, ràng wǒ lái jiē nǐmen."}, {"speaker": "白家月/安妮", "cn": "谢谢您。", "pinyin": "Xièxie nín."}, {"speaker": "王一雪", "cn": "不客气。", "pinyin": "Bù kèqi."}], "translation_vn": "Bạch Gia Nguyệt: Xin hỏi, chị là chị gái của cô Vương Nhất Phi phải không ạ?\nVương Nhất Tuyết: Đúng rồi, các em là học sinh của cô ấy phải không?\nBạch Gia Nguyệt: Vâng ạ, em là Bạch Gia Nguyệt, bạn ấy là Annie.\nVương Nhất Tuyết: Chào các em. Chị tên là Vương Nhất Tuyết. Nhất Phi đã gọi điện thoại cho chị, nhờ chị đến đón các em.\nBạch Gia Nguyệt, Annie: Chúng em cảm ơn chị ạ.\nVương Nhất Tuyết: Đừng khách sáo vậy.", "audio_dialogue": "1-1.mp3", "audio_vocab": "1-2.mp3"}, {"label": "Bài khóa 2", "type": "dialogue", "lines": [{"speaker": "王一雪", "cn": "你们是第一次来北京吗？", "pinyin": "Nǐmen shì dì-yī cì lái Běijīng ma?"}, {"speaker": "白家月", "cn": "是的，我们都是第一次来。", "pinyin": "Shì de, wǒmen dōu shì dì-yī cì lái."}, {"speaker": "王一雪", "cn": "你们是来学中文的吗？", "pinyin": "Nǐmen shì lái xué Zhōngwén de ma?"}, {"speaker": "安妮", "cn": "不是，我们是来旅游的。", "pinyin": "Bú shì, wǒmen shì lái lǚyóu de."}, {"speaker": "王一雪", "cn": "我这几天都不忙，你们有事就找我。", "pinyin": "Wǒ zhè jǐ tiān dōu bù máng, nǐmen yǒu shì jiù zhǎo wǒ."}, {"speaker": "白家月", "cn": "好的，谢谢您。", "pinyin": "Hǎo de, xièxie nín."}], "translation_vn": "Vương Nhất Tuyết: Đây là lần đầu các em đến Bắc Kinh phải không?\nBạch Gia Nguyệt: Vâng ạ, chúng em đều là lần đầu tiên đến đây ạ.\nVương Nhất Tuyết: Các em đến học tiếng Trung Quốc à?\nAnnie: Không phải, chúng em đến du lịch ạ.\nVương Nhất Tuyết: Mấy hôm nay chị đều không bận, các em có việc gì thì cứ tìm chị nhé.\nBạch Gia Nguyệt: Vâng ạ, cảm ơn chị.", "audio_dialogue": "1-3.mp3", "audio_vocab": "1-4.mp3"}, {"label": "Bài khóa 3", "type": "dialogue", "lines": [{"speaker": "陈天中", "cn": "喂，家月，你明天有时间吗？我想请你帮个忙。", "pinyin": "Wéi, Jiāyuè, nǐ míngtiān yǒu shíjiān ma? Wǒ xiǎng qǐng nǐ bāng ge máng."}, {"speaker": "白家月", "cn": "不好意思，天中，我已经到北京了。", "pinyin": "Bù hǎoyìsi, Tiānzhōng, wǒ yǐjīng dào Běijīng le."}, {"speaker": "陈天中", "cn": "你是什么时候到的？", "pinyin": "Nǐ shì shénme shíhou dào de?"}, {"speaker": "白家月", "cn": "我是今天早上到的。你有事可以叫李文帮忙，他还在学校呢。", "pinyin": "Wǒ shì jīntiān zǎoshang dào de. Nǐ yǒu shì kěyǐ jiào Lǐ Wén bāngmáng, tā hái zài xuéxiào ne."}, {"speaker": "陈天中", "cn": "好的，那我给他打个电话。", "pinyin": "Hǎo de, nà wǒ gěi tā dǎ ge diànhuà."}, {"speaker": "白家月", "cn": "好，再见！", "pinyin": "Hǎo, zàijiàn!"}], "translation_vn": "Trần Thiên Trung: Alô, Gia Nguyệt à, mai bạn có thời gian không? Mình muốn nhờ bạn giúp một việc.\nBạch Gia Nguyệt: Xin lỗi Thiên Trung nhé, mình đã đến Bắc Kinh rồi.\nTrần Thiên Trung: Bạn đến khi nào vậy?\nBạch Gia Nguyệt: Sáng hôm nay mình đến. Nếu bạn cần giúp đỡ gì thì có thể nhờ Lý Văn nhé, bạn ấy vẫn đang ở trường.\nTrần Thiên Trung: Được rồi, vậy mình sẽ gọi điện thoại cho bạn ấy.\nBạch Gia Nguyệt: Ừ, tạm biệt nhé.", "audio_dialogue": "1-5 @xitoytili_luoluodafang.mp3", "audio_vocab": "1-6 @xitoytili_luoluodafang.mp3"}, {"label": "Bài khóa 4", "type": "passage", "lines": [{"speaker": "", "cn": "王老师，我们已经到北京了，是您姐姐来接的我们。她请我们吃了北京烤鸭，还给我们介绍了很多东西。我们的中文不太好，有时不太懂她的意思。", "pinyin": "Wáng lǎoshī, wǒmen yǐjīng dào Běijīng le, shì nín jiějie lái jiē de wǒmen. Tā qǐng wǒmen chīle Běijīng Kǎoyā, hái gěi wǒmen jièshàole hěnduō dōngxi. Wǒmen de Zhōngwén bù tài hǎo, yǒushí bù tài dǒng tā de yìsi."}], "translation_vn": "Thưa cô Vương, chúng em đã tới Bắc Kinh rồi, chị gái của cô đã tới đón chúng em. Chị ấy đã mời chúng em ăn vịt quay Bắc Kinh, còn giới thiệu cho chúng em rất nhiều thứ. Tiếng Trung Quốc của chúng em không tốt lắm, đôi khi chưa hiểu hết ý của chị ấy.", "audio_dialogue": "1-7 @xitoytili_luoluodafang.mp3", "audio_vocab": "1-8 @xitoytili_luoluodafang.mp3"}]}, {"id": 2, "title_cn": "还是打车去北大吧", "title_pinyin": "Háishi dǎchē qù Běidà ba", "title_vn": "Chúng ta vẫn nên gọi taxi đi Đại học Bắc Kinh nhé", "goals": ["Có thể nghe hiểu và giới thiệu được thông tin cơ bản của một trường học.", "Có thể nghe hiểu và sử dụng được \"多\" để diễn đạt số lượng ước lượng.", "Nắm vững cách dùng của cấu trúc cố định \"还是……吧\" để diễn đạt sự lựa chọn.", "Hiểu về Đại học Bắc Kinh – một trường đại học danh tiếng của Trung Quốc."], "vocab": [{"hanzi": "公交车", "pinyin": "gōngjiāochē", "pos": "dt.", "vn": "xe buýt"}, {"hanzi": "但", "pinyin": "dàn", "pos": "liên.", "vn": "nhưng, nhưng mà"}, {"hanzi": "车站", "pinyin": "chēzhàn", "pos": "dt.", "vn": "bến xe buýt"}, {"hanzi": "远", "pinyin": "yuǎn", "pos": "tt.", "vn": "xa"}, {"hanzi": "打车", "pinyin": "dǎchē", "pos": "dgt.", "vn": "gọi xe, đi xe, bắt (taxi)"}, {"hanzi": "还是", "pinyin": "háishi", "pos": "phó.", "vn": "vẫn, tốt hơn là..."}, {"hanzi": "北京大学", "pinyin": "Běijīng Dàxué", "pos": "danh từ riêng", "vn": "Đại học Bắc Kinh"}, {"hanzi": "啊", "pinyin": "a", "pos": "trợ.", "vn": "trợ từ ngữ khí"}, {"hanzi": "万", "pinyin": "wàn", "pos": "số.", "vn": "vạn, mười nghìn"}, {"hanzi": "名", "pinyin": "míng", "pos": "lượng./dt.", "vn": "(lượng từ chỉ người); thứ hạng trong cuộc thi, tên"}, {"hanzi": "网上", "pinyin": "wǎngshang", "pos": "dt.", "vn": "trên mạng"}, {"hanzi": "外国", "pinyin": "wàiguó", "pos": "dt.", "vn": "nước ngoài"}, {"hanzi": "间", "pinyin": "jiān", "pos": "lượng.", "vn": "gian, căn (phòng)"}, {"hanzi": "教室", "pinyin": "jiàoshì", "pos": "dt.", "vn": "phòng học"}, {"hanzi": "票", "pinyin": "piào", "pos": "dt.", "vn": "vé"}, {"hanzi": "别", "pinyin": "bié", "pos": "phó.", "vn": "đừng"}, {"hanzi": "过来", "pinyin": "guòlái", "pos": "dgt.", "vn": "đến, đến đây"}], "grammar": [{"title": "固定格式“还是……吧”", "explanation_vn": "Cấu trúc cố định \"还是……吧\" dùng để chỉ lựa chọn thiên về một hướng nào đó, có ý \"làm vậy sẽ tốt hơn\".", "examples": [{"cn": "我还是打车去吧。", "pinyin": "Wǒ háishi dǎchē qù ba.", "vn": ""}, {"cn": "那件衣服很好看，还是买那件吧。", "pinyin": "Nà jiàn yīfu hěn hǎokàn, háishi mǎi nà jiàn ba.", "vn": ""}, {"cn": "你第一次去北京，还是找个人接你吧。", "pinyin": "Nǐ dì-yī cì qù Běijīng, háishi zhǎo ge rén jiē nǐ ba.", "vn": ""}]}, {"title": "用“多”表达概数", "explanation_vn": "\"多\" được đặt sau số từ hoặc số lượng từ để chỉ số lẻ (có dư). Khi con số là bội số của 10, \"多\" thường đặt sau số từ; khi con số không phải là bội số của 10, \"多\" thường đặt sau lượng từ.", "examples": [{"cn": "北京大学有四万多名学生呢！", "pinyin": "Běijīng Dàxué yǒu sìwàn duō míng xuésheng ne!", "vn": ""}, {"cn": "教室里有二十多个学生。", "pinyin": "Jiàoshì lǐ yǒu èrshí duō ge xuésheng.", "vn": ""}, {"cn": "这两个苹果五块多钱。", "pinyin": "Zhè liǎng ge píngguǒ wǔ kuài duō qián.", "vn": ""}]}, {"title": "动词或动词性短语、主谓短语作定语", "explanation_vn": "Động từ, cụm động từ, cụm chủ vị đặt trước danh từ, biểu thị đặc trưng hoặc trạng thái của danh từ.", "examples": [{"cn": "他们卖的电影票也很便宜。", "pinyin": "Tāmen mài de diànyǐngpiào yě hěn piányi.", "vn": ""}, {"cn": "现在学中文的学生很多。", "pinyin": "Xiànzài xué Zhōngwén de xuésheng hěn duō.", "vn": ""}, {"cn": "这是朋友给我的杯子。", "pinyin": "Zhè shì péngyou gěi wǒ de bēizi.", "vn": ""}]}], "texts": [{"label": "Bài khóa 1", "type": "dialogue", "lines": [{"speaker": "白家月", "cn": "请问，这儿有到北京大学的公交车吗？", "pinyin": "Qǐngwèn, zhèr yǒu dào Běijīng Dàxué de gōngjiāochē ma?"}, {"speaker": "服务员", "cn": "有，但车站有点儿远。", "pinyin": "Yǒu, dàn chēzhàn yǒudiǎn yuǎn."}, {"speaker": "白家月", "cn": "这儿好打车吗？", "pinyin": "Zhèr hǎo dǎchē ma?"}, {"speaker": "服务员", "cn": "好打车。", "pinyin": "Hǎo dǎchē."}, {"speaker": "白家月", "cn": "谢谢。安妮，我们还是打车去吧。", "pinyin": "Xièxie. Ānní, wǒmen háishi dǎchē qù ba."}, {"speaker": "安妮", "cn": "好，没问题。", "pinyin": "Hǎo, méi wèntí."}], "translation_vn": "Bạch Gia Nguyệt: Xin hỏi, ở đây có xe buýt đi đến Đại học Bắc Kinh không?\nNhân viên phục vụ: Có đấy, nhưng bến xe buýt hơi xa.\nBạch Gia Nguyệt: Ở đây gọi xe taxi có dễ không vậy?\nNhân viên phục vụ: Dễ gọi.\nBạch Gia Nguyệt: Cảm ơn! Annie, chúng ta vẫn nên gọi xe taxi đi thôi.\nAnnie: Được, không vấn đề gì cả.", "audio_dialogue": "2-1 @xitoytili_luoluodafang.mp3", "audio_vocab": "2-2 @xitoytili_luoluodafang.mp3"}, {"label": "Bài khóa 2", "type": "dialogue", "lines": [{"speaker": "白家月", "cn": "学校里人真多啊！", "pinyin": "Xuéxiào lǐ rén zhēn duō a!"}, {"speaker": "安妮", "cn": "是啊，北京大学有四万多名学生呢！", "pinyin": "Shì a, Běijīng Dàxué yǒu sìwàn duō míng xuésheng ne!"}, {"speaker": "白家月", "cn": "你是怎么知道的？", "pinyin": "Nǐ shì zěnme zhīdào de?"}, {"speaker": "安妮", "cn": "是网上说的，网上还说北京大学有三千多名外国学生。", "pinyin": "Shì wǎngshàng shuō de, wǎngshàng hái shuō Běijīng Dàxué yǒu sānqiān duō míng wàiguó xuésheng."}, {"speaker": "白家月", "cn": "我也想来这儿学习。", "pinyin": "Wǒ yě xiǎng lái zhèr xuéxí."}, {"speaker": "安妮", "cn": "那边就有一间教室，我们去看一下吧。", "pinyin": "Nàbiān jiù yǒu yì jiān jiàoshì, wǒmen qù kàn yíxià ba."}], "translation_vn": "Bạch Gia Nguyệt: Trường học đông người quá!\nAnnie: Đúng vậy, Đại học Bắc Kinh có hơn 40 000 sinh viên.\nBạch Gia Nguyệt: Làm sao bạn biết được thế?\nAnnie: Là thông tin trên mạng nói vậy, trên mạng còn cho biết Đại học Bắc Kinh có hơn 3 000 sinh viên nước ngoài.\nBạch Gia Nguyệt: Mình cũng muốn đến đây học tập.\nAnnie: Đằng kia có một phòng học, chúng ta đến xem đi.", "audio_dialogue": "2-3 @xitoytili_luoluodafang.mp3", "audio_vocab": "2-4 @xitoytili_luoluodafang.mp3"}, {"label": "Bài khóa 3", "type": "dialogue", "lines": [{"speaker": "安妮", "cn": "家月，你看，学校里有家电影院！", "pinyin": "Jiāyuè, nǐ kàn, xuéxiào lǐ yǒu jiā diànyǐngyuàn!"}, {"speaker": "白家月", "cn": "是啊，电影院还不小。", "pinyin": "Shì a, diànyǐngyuàn hái bù xiǎo."}, {"speaker": "安妮", "cn": "他们卖的电影票也很便宜。", "pinyin": "Tāmen mài de diànyǐngpiào yě hěn piányi."}, {"speaker": "白家月", "cn": "天啊！有的还不到二十块钱。", "pinyin": "Tiān a! Yǒude hái bú dào èrshí kuài qián."}, {"speaker": "安妮", "cn": "那你想不想去看个电影？", "pinyin": "Nà nǐ xiǎng bu xiǎng qù kàn ge diànyǐng?"}, {"speaker": "白家月", "cn": "还是别看电影了，北京大学就很好看！", "pinyin": "Háishi bié kàn diànyǐng le, Běijīng Dàxué jiù hěn hǎokàn!"}], "translation_vn": "Annie: Gia Nguyệt, bạn nhìn kìa, trong trường có rạp chiếu phim đấy!\nBạch Gia Nguyệt: Đúng rồi, rạp chiếu phim cũng không nhỏ.\nAnnie: Họ bán vé xem phim cũng rất rẻ nhé.\nBạch Gia Nguyệt: Trời, có loại vé còn không đến 20 đồng kia.\nAnnie: Thế bạn có muốn đi xem phim không?\nBạch Gia Nguyệt: Thôi đừng xem phim nữa, Đại học Bắc Kinh đã rất đẹp rồi.", "audio_dialogue": "2-5 @xitoytili_luoluodafang.mp3", "audio_vocab": "2-6 @xitoytili_luoluodafang.mp3"}, {"label": "Bài khóa 4", "type": "passage", "lines": [{"speaker": "", "cn": "北京大学很大，有四万多名学生。学校很漂亮，里边还有家电影院，电影票也不贵。我们有时间还想再过来看个电影。", "pinyin": "Běijīng Dàxué hěn dà, yǒu sìwàn duō míng xuésheng. Xuéxiào hěn piàoliang, lǐbian hái yǒu jiā diànyǐngyuàn, diànyǐngpiào yě bù guì. Wǒmen yǒu shíjiān hái xiǎng zài guòlái kàn ge diànyǐng."}], "translation_vn": "Đại học Bắc Kinh rất lớn, có hơn 40 000 sinh viên. Trường rất đẹp, trong trường còn có rạp chiếu phim, vé xem phim cũng không đắt, chúng tôi vẫn muốn quay lại để xem phim nếu có thời gian.", "audio_dialogue": "2-7.mp3", "audio_vocab": "2-8 @xitoytili_luoluodafang.mp3"}]}, {"id": 3, "title_cn": "我想去西安旅游", "title_pinyin": "Wǒ xiǎng qù Xī'ān lǚyóu", "title_vn": "Em muốn đi Tây An du lịch", "goals": ["Có thể nghe hiểu và hỏi được nguyên nhân của sự việc.", "Nắm vững cách dùng của bổ ngữ kết quả để miêu tả kết quả của hành động.", "Nắm vững cách dùng của động từ lặp lại để diễn đạt thời gian ngắn của hành động, số lượng ít hoặc thử làm gì.", "Hiểu về các điểm tham quan du lịch ở Tây An."], "vocab": [{"hanzi": "回来", "pinyin": "huílái", "pos": "dgt.", "vn": "quay về, quay lại"}, {"hanzi": "这么", "pinyin": "zhème", "pos": "đt.", "vn": "như vậy"}, {"hanzi": "完", "pinyin": "wán", "pos": "dgt.", "vn": "xong"}, {"hanzi": "一起", "pinyin": "yìqǐ", "pos": "phó.", "vn": "cùng, cùng nhau"}, {"hanzi": "出去", "pinyin": "chūqù", "pos": "dgt.", "vn": "đi ra, đi khỏi, đi"}, {"hanzi": "洗", "pinyin": "xǐ", "pos": "dgt.", "vn": "rửa"}, {"hanzi": "自己", "pinyin": "zìjǐ", "pos": "đt.", "vn": "tự, tự thân, bản thân"}, {"hanzi": "拿", "pinyin": "ná", "pos": "dgt.", "vn": "cầm, nắm"}, {"hanzi": "手", "pinyin": "shǒu", "pos": "dt.", "vn": "tay"}, {"hanzi": "为什么", "pinyin": "wèi shénme", "pos": "tr.", "vn": "vì sao, tại sao"}, {"hanzi": "不错", "pinyin": "búcuò", "pos": "tt.", "vn": "không tồi, hay"}, {"hanzi": "送", "pinyin": "sòng", "pos": "dgt.", "vn": "đưa, tiễn, tặng"}, {"hanzi": "回去", "pinyin": "huíqù", "pos": "dgt.", "vn": "quay về, về"}, {"hanzi": "每", "pinyin": "měi", "pos": "đt.", "vn": "mỗi, hàng (ngày, năm...)"}, {"hanzi": "累", "pinyin": "lèi", "pos": "tt.", "vn": "mệt"}], "grammar": [{"title": "结果补语", "explanation_vn": "Có một số động từ hoặc tính từ có thể đặt sau động từ để biểu thị kết quả của hành động. Hình thức phủ định là thêm \"没（有）\" vào trước động từ và bỏ \"了\" ở cuối câu. Hình thức nghi vấn có 3 loại: (1) thêm \"了吗\" vào cuối câu; (2) thêm \"（了）没有\" vào cuối câu; (3) động từ + 没 + động từ + bổ ngữ kết quả.", "examples": [{"cn": "菜都做好了。", "pinyin": "Cài dōu zuòhǎo le.", "vn": ""}, {"cn": "我吃完饭了。", "pinyin": "Wǒ chī wán fàn le.", "vn": ""}, {"cn": "小雪今天来晚了。", "pinyin": "Xiǎoxuě jīntiān lái wǎn le.", "vn": ""}, {"cn": "我没吃完饭。", "pinyin": "Wǒ méi chī wán fàn.", "vn": ""}, {"cn": "小雪没来晚。", "pinyin": "Xiǎoxuě méi lái wǎn.", "vn": ""}, {"cn": "你吃完饭了吗？", "pinyin": "Nǐ chī wán fàn le ma?", "vn": ""}, {"cn": "小雪来晚了没有？", "pinyin": "Xiǎoxuě lái wǎn le méiyǒu?", "vn": ""}, {"cn": "你学没学会？", "pinyin": "Nǐ xué méi xuéhuì?", "vn": ""}]}, {"title": "动词重叠（1）", "explanation_vn": "Động từ có tính hành động mạnh, có thể lặp đi lặp lại hoặc duy trì thì đều có thể lặp lại. Động từ lặp lại thường dùng trong văn nói, mang ngữ khí nhẹ nhàng, tự nhiên, biểu thị thời gian ngắn, số lượng ít hoặc mang sắc thái thử nghiệm. Hình thức lặp lại của động từ đơn âm tiết là \"A（一）A\"; hình thức lặp lại của động từ song âm tiết là \"ABAB\"; hình thức lặp lại của từ ly hợp là \"AAB\".", "examples": [{"cn": "那你再想一想，你想好了，我来买票。", "pinyin": "Nà nǐ zài xiǎng yi xiǎng, nǐ xiǎnghǎo le, wǒ lái mǎipiào.", "vn": ""}, {"cn": "我有点儿累，现在想休息休息。", "pinyin": "Wǒ yǒudiǎnr lèi, xiànzài xiǎng xiūxi xiūxi.", "vn": ""}, {"cn": "你能过来帮帮忙吗？", "pinyin": "Nǐ néng guòlái bāngbāngmáng ma?", "vn": ""}]}, {"title": "动词重叠（2）", "explanation_vn": "Khi diễn đạt tình huống đã xảy ra, hình thức lặp lại của động từ đơn âm tiết là \"A了A\"; động từ song âm tiết nói chung không dùng hình thức lặp lại, mà chỉ dùng cấu trúc \"AB了一下\"; hình thức lặp lại của từ ly hợp là \"A了AB\".", "examples": [{"cn": "我看了看网上的介绍。", "pinyin": "Wǒ kànle kàn wǎngshàng de jièshào.", "vn": ""}, {"cn": "我休息了一下，现在觉得不累了。", "pinyin": "Wǒ xiūxile yíxià, xiànzài juéde bú lèi le.", "vn": ""}, {"cn": "他昨天来帮了帮忙。", "pinyin": "Tā zuótiān lái bāngle bāngmáng.", "vn": ""}]}], "texts": [{"label": "Bài khóa 1", "type": "dialogue", "lines": [{"speaker": "王一雪", "cn": "今天回来这么晚啊！", "pinyin": "Jīntiān huílái zhème wǎn a!"}, {"speaker": "刘明", "cn": "工作太多了，下班的时候没做完。", "pinyin": "Gōngzuò tài duō le, xiàbān de shíhou méi zuòwán."}, {"speaker": "王一雪", "cn": "菜都做好了，过来吃饭吧。", "pinyin": "Cài dōu zuòhǎo le, guòlái chī fàn ba."}, {"speaker": "刘明", "cn": "我想休息一下，喝杯水。", "pinyin": "Wǒ xiǎng xiūxi yíxià, hē bēi shuǐ."}, {"speaker": "王一雪", "cn": "好的。", "pinyin": "Hǎo de."}], "translation_vn": "Vương Nhất Tuyết: Hôm nay anh về muộn thế!\nLưu Minh: Anh có nhiều việc quá, đến giờ tan làm mà vẫn chưa xong.\nVương Nhất Tuyết: Cơm nấu xong rồi. Anh ra ăn cơm nhé.\nLưu Minh: Anh muốn nghỉ ngơi một lát, uống cốc nước đã.\nVương Nhất Tuyết: Vâng ạ.", "audio_dialogue": "3-1.mp3", "audio_vocab": "3-2.mp3"}, {"label": "Bài khóa 2", "type": "dialogue", "lines": [{"speaker": "刘明", "cn": "我们找个时间去旅游，怎么样？", "pinyin": "Wǒmen zhǎo ge shíjiān qù lǚyóu, zěnmeyàng?"}, {"speaker": "王一雪", "cn": "好啊，我也很想一起出去玩。", "pinyin": "Hǎo a, wǒ yě hěn xiǎng yìqǐ chūqù wán."}, {"speaker": "刘明", "cn": "你想去哪儿？", "pinyin": "Nǐ xiǎng qù nǎr?"}, {"speaker": "王一雪", "cn": "我还没想好呢。", "pinyin": "Wǒ hái méi xiǎnghǎo ne."}, {"speaker": "刘明", "cn": "那你再想一想，你想好了，我来买票。", "pinyin": "Nà nǐ zài xiǎng yi xiǎng, nǐ xiǎnghǎo le, wǒ lái mǎipiào."}], "translation_vn": "Lưu Minh: Chúng ta sắp xếp thời gian đi du lịch, em thấy thế nào?\nVương Nhất Tuyết: Nhất trí! Em cũng rất muốn đi chơi cùng anh.\nLưu Minh: Em muốn đi đâu?\nVương Nhất Tuyết: Em vẫn chưa nghĩ ra.\nLưu Minh: Vậy em cứ nghĩ thêm nhé. Khi nào em nghĩ xong, anh sẽ mua vé.", "audio_dialogue": "3-3.mp3", "audio_vocab": "3-4 @xitoytili_luoluodafang.mp3"}, {"label": "Bài khóa 3", "type": "dialogue", "lines": [{"speaker": "刘明", "cn": "吃个苹果吧，我都洗好了。", "pinyin": "Chī ge píngguǒ ba, wǒ dōu xǐhǎo le."}, {"speaker": "王一雪", "cn": "好的。", "pinyin": "Hǎo de."}, {"speaker": "刘明", "cn": "就在桌子上，你自己拿。", "pinyin": "Jiù zài zhuōzi shang, nǐ zìjǐ ná."}, {"speaker": "王一雪", "cn": "我去洗洗手。对了，我们去西安旅游，怎么样？", "pinyin": "Wǒ qù xǐxi shǒu. Duìle, wǒmen qù Xī'ān lǚyóu, zěnmeyàng?"}, {"speaker": "刘明", "cn": "为什么想去西安？", "pinyin": "Wèi shénme xiǎng qù Xī'ān?"}, {"speaker": "王一雪", "cn": "我看了看网上的介绍，这个时候去西安很不错！", "pinyin": "Wǒ kànle kàn wǎngshàng de jièshào, zhège shíhou qù Xī'ān hěn búcuò!"}], "translation_vn": "Lưu Minh: Ăn quả táo đi, anh đã rửa sạch rồi.\nVương Nhất Tuyết: Vâng ạ.\nLưu Minh: Táo để trên bàn, em tự đi lấy nhé.\nVương Nhất Tuyết: Em đi rửa tay đã. À đúng rồi, mình đi Tây An du lịch, anh thấy thế nào?\nLưu Minh: Vì sao em muốn đi Tây An?\nVương Nhất Tuyết: Em có xem qua giới thiệu trên mạng. Thời điểm này đi Tây An rất tuyệt!", "audio_dialogue": "3-5.mp3", "audio_vocab": "3-6.mp3"}, {"label": "Bài khóa 4", "type": "passage", "lines": [{"speaker": "", "cn": "早上，刘明开车送孩子去学校，送完孩子回家后，医院就来电话了，让他回去上班。我觉得他这个月每天都很累，真想让他休息休息。", "pinyin": "Zǎoshang, Liú Míng kāichē sòng háizi qù xuéxiào, sòngwán háizi huí jiā hòu, yīyuàn jiù lái diànhuà le, ràng tā huíqù shàngbān. Wǒ juéde tā zhège yuè měitiān dōu hěn lèi, zhēn xiǎng ràng tā xiūxi xiūxi."}], "translation_vn": "Buổi sáng, Lưu Minh lái xe đưa con đi đến trường, sau khi đưa con xong quay về nhà thì bệnh viện gọi điện đến, yêu cầu anh ấy quay về bệnh viện làm việc. Tôi cảm thấy tháng này ngày nào Lưu Minh cũng đều rất bận, thật muốn anh ấy được nghỉ ngơi một chút.", "audio_dialogue": "3-7.mp3", "audio_vocab": "3-8.mp3"}]}, {"id": 4, "title_cn": "你穿红色的很好看", "title_pinyin": "Nǐ chuān hóngsè de hěn hǎokàn", "title_vn": "Con mặc đồ màu đỏ rất đẹp", "goals": ["Có thể nghe hiểu và hỏi về những trải nghiệm trong quá khứ.", "Có thể nghe hiểu và sử dụng được cách thức miêu tả đối tượng được đề cập đến.", "Nắm vững cách dùng của câu ghép nhân quả \"因为……，所以……\", để diễn đạt nguyên nhân và kết quả của sự việc."], "vocab": [{"hanzi": "过", "pinyin": "guo", "pos": "trợ.", "vn": "đã từng"}, {"hanzi": "商场", "pinyin": "shāngchǎng", "pos": "dt.", "vn": "trung tâm thương mại, khu mua sắm"}, {"hanzi": "进去", "pinyin": "jìnqù", "pos": "đgt.", "vn": "đi vào"}, {"hanzi": "条", "pinyin": "tiáo", "pos": "lượng.", "vn": "cái, chiếc (quần, váy...)"}, {"hanzi": "裤子", "pinyin": "kùzi", "pos": "dt.", "vn": "quần"}, {"hanzi": "白色", "pinyin": "báisè", "pos": "dt.", "vn": "màu trắng"}, {"hanzi": "因为", "pinyin": "yīnwèi", "pos": "liên.", "vn": "bởi vì, vì"}, {"hanzi": "试", "pinyin": "shì", "pos": "đgt.", "vn": "thử"}, {"hanzi": "红色", "pinyin": "hóngsè", "pos": "dt.", "vn": "màu đỏ"}, {"hanzi": "所以", "pinyin": "suǒyǐ", "pos": "liên.", "vn": "cho nên, nên"}, {"hanzi": "书包", "pinyin": "shūbāo", "pos": "dt.", "vn": "cặp sách"}, {"hanzi": "过去", "pinyin": "guòqù", "pos": "đgt.", "vn": "sang, đi sang"}, {"hanzi": "绿色", "pinyin": "lǜsè", "pos": "dt.", "vn": "màu xanh lá cây"}, {"hanzi": "黑色", "pinyin": "hēisè", "pos": "dt.", "vn": "màu đen"}, {"hanzi": "更", "pinyin": "gèng", "pos": "phó.", "vn": "càng, hơn"}, {"hanzi": "颜色", "pinyin": "yánsè", "pos": "dt.", "vn": "màu sắc"}], "grammar": [{"title": "动态助词\"过\" - Trợ từ động thái \"过\"", "explanation_vn": "Trợ từ động thái \"过\" đặt sau động từ, biểu thị động tác đã từng xảy ra trong quá khứ, không kéo dài đến hiện tại. Cấu trúc cơ bản: Chủ ngữ + động từ + 过 + tân ngữ. Hình thức phủ định là thêm \"没（有）\" trước động từ. Hình thức nghi vấn có 3 dạng: (1) cuối câu thêm \"吗\"; (2) cuối câu thêm \"没有\"; (3) động từ + 没 + động từ + 过.", "examples": [{"cn": "她去过中国。", "pinyin": "Tā qùguo Zhōngguó.", "vn": ""}, {"cn": "我吃过饺子，很好吃。", "pinyin": "Wǒ chīguo jiǎozi, hěn hǎochī.", "vn": ""}, {"cn": "她没去过中国。", "pinyin": "Tā méi qùguo Zhōngguó.", "vn": ""}, {"cn": "我们来过这家商场吗？", "pinyin": "Wǒmen láiguo zhè jiā shāngchǎng ma?", "vn": ""}, {"cn": "陈天中吃过饺子没有？", "pinyin": "Chén Tiānzhōng chīguo jiǎozi méiyǒu?", "vn": ""}, {"cn": "你看没看过那个电影？", "pinyin": "Nǐ kàn méi kànguo nàge diànyǐng?", "vn": ""}]}, {"title": "因果复句\"因为……，所以……\" - Câu ghép nhân quả \"因为……，所以……\"", "explanation_vn": "Câu ghép nguyên nhân kết quả được tạo thành bởi cấu trúc \"因为……所以……\". \"因为\" và \"所以\" có thể sử dụng thành đôi, cũng có thể chỉ dùng một trong hai từ này.", "examples": [{"cn": "就是因为没穿过，所以要试试啊！", "pinyin": "Jiùshì yīnwèi méi chuānguo, suǒyǐ yào shìshi a!", "vn": ""}, {"cn": "因为我生病了，今天没去上班。", "pinyin": "Yīnwèi wǒ shēngbìng le, jīntiān méi qù shàngbān.", "vn": ""}, {"cn": "我没去过他家，所以让他来车站接我。", "pinyin": "Wǒ méi qùguo tā jiā, suǒyǐ ràng tā lái chēzhàn jiē wǒ.", "vn": ""}]}, {"title": "\"的\"字短语 - Cụm từ chứa \"的\"", "explanation_vn": "Trợ từ kết cấu \"的\" đặt sau danh từ, đại từ, động từ, tính từ... tạo thành cụm từ chứa \"的\", cụm từ này sẽ tương đương với một cụm danh từ.", "examples": [{"cn": "红色的、绿色的、黑色的，你想买哪个？（=红色的书包、绿色的书包、黑色的书包）", "pinyin": "Hóngsè de, lǜsè de, hēisè de, nǐ xiǎng mǎi nǎge? (= Hóngsè de shūbāo, lǜsè de shūbāo, hēisè de shūbāo)", "vn": ""}, {"cn": "这个面包是爸爸买的，妈妈买的在那儿。（=买的面包）", "pinyin": "Zhège miànbāo shì bàba mǎi de, māma mǎi de zài nàr. (= mǎi de miànbāo)", "vn": ""}, {"cn": "这件衣服太贵了，还是那件便宜的吧。（=便宜的衣服）", "pinyin": "Zhè jiàn yīfu tài guì le, háishi nà jiàn piányi de ba. (= piányi de yīfu)", "vn": ""}]}], "texts": [{"label": "Bài khóa 1", "type": "dialogue", "lines": [{"speaker": "刘小雪 (Lưu Tiểu Tuyết)", "cn": "妈妈，我们来过这家商场吗？", "pinyin": "Māma, wǒmen láiguo zhè jiā shāngchǎng ma?"}, {"speaker": "王一雪 (Vương Nhất Tuyết)", "cn": "没来过，这是新开的。", "pinyin": "Méi láiguo, zhè shì xīn kāi de."}, {"speaker": "刘小雪 (Lưu Tiểu Tuyết)", "cn": "我们进去看看吧。", "pinyin": "Wǒmen jìnqù kànkan ba."}, {"speaker": "王一雪 (Vương Nhất Tuyết)", "cn": "好啊！你想买点儿什么？", "pinyin": "Hǎo a! Nǐ xiǎng mǎi diǎnr shénme?"}, {"speaker": "刘小雪 (Lưu Tiểu Tuyết)", "cn": "我想买条裤子。", "pinyin": "Wǒ xiǎng mǎi tiáo kùzi."}, {"speaker": "王一雪 (Vương Nhất Tuyết)", "cn": "没问题。", "pinyin": "Méi wèntí."}], "translation_vn": "Lưu Tiểu Tuyết: Mẹ ơi, chúng ta đã từng đến trung tâm mua sắm này chưa?\nVương Nhất Tuyết: Chưa con ạ, đây là trung tâm mua sắm mới mở.\nLưu Tiểu Tuyết: Chúng ta đi vào xem một chút nhé.\nVương Nhất Tuyết: Được thôi. Con muốn mua chút gì không?\nLưu Tiểu Tuyết: Con muốn mua chiếc quần.\nVương Nhất Tuyết: Được nhé.", "audio_dialogue": "4-1 @xitoytili_luoluodafang.mp3", "audio_vocab": "4-2.mp3"}, {"label": "Bài khóa 2", "type": "dialogue", "lines": [{"speaker": "刘小雪 (Lưu Tiểu Tuyết)", "cn": "妈妈，我想买这条白色的裤子。", "pinyin": "Māma, wǒ xiǎng mǎi zhè tiáo báisè de kùzi."}, {"speaker": "王一雪 (Vương Nhất Tuyết)", "cn": "你有很多白色的衣服，为什么还买白色的？", "pinyin": "Nǐ yǒu hěn duō báisè de yīfu, wèishénme hái mǎi báisè de?"}, {"speaker": "刘小雪 (Lưu Tiểu Tuyết)", "cn": "因为我喜欢白色啊！", "pinyin": "Yīnwèi wǒ xǐhuan báisè a!"}, {"speaker": "王一雪 (Vương Nhất Tuyết)", "cn": "我觉得这条白色的不太好看，你试试那条红色的吧。", "pinyin": "Wǒ juéde zhè tiáo báisè de bú tài hǎokàn, nǐ shìshi nà tiáo hóngsè de ba."}, {"speaker": "刘小雪 (Lưu Tiểu Tuyết)", "cn": "我没穿过红色的，红色的好看吗？", "pinyin": "Wǒ méi chuānguo hóngsè de, hóngsè de hǎokàn ma?"}, {"speaker": "王一雪 (Vương Nhất Tuyết)", "cn": "就是因为没穿过，所以要试试啊！", "pinyin": "Jiù shì yīnwèi méi chuānguo, suǒyǐ yào shìshi a!"}], "translation_vn": "Lưu Tiểu Tuyết: Mẹ ơi, con muốn mua chiếc quần màu trắng này.\nVương Nhất Tuyết: Con đã có rất nhiều quần áo màu trắng rồi, sao vẫn còn mua màu trắng nữa?\nLưu Tiểu Tuyết: Vì con thích màu trắng ạ.\nVương Nhất Tuyết: Mẹ thấy chiếc quần màu trắng này không đẹp lắm, con thử chiếc màu đỏ kia xem sao.\nLưu Tiểu Tuyết: Con chưa từng mặc quần màu đỏ, quần màu đỏ có đẹp không mẹ?\nVương Nhất Tuyết: Chính là vì chưa từng mặc nên cần phải thử xem.", "audio_dialogue": "4-3.mp3", "audio_vocab": "4-4 @xitoytili_luoluodafang.mp3"}, {"label": "Bài khóa 3", "type": "dialogue", "lines": [{"speaker": "刘小雪 (Lưu Tiểu Tuyết)", "cn": "妈妈，我想买个新书包。", "pinyin": "Māma, wǒ xiǎng mǎi gè xīn shūbāo."}, {"speaker": "王一雪 (Vương Nhất Tuyết)", "cn": "好，那边卖书包，我们过去看看吧。", "pinyin": "Hǎo, nàbian mài shūbāo, wǒmen guòqù kànkan ba."}, {"speaker": "刘小雪 (Lưu Tiểu Tuyết)", "cn": "这么多漂亮的书包！", "pinyin": "Zhème duō piàoliang de shūbāo!"}, {"speaker": "王一雪 (Vương Nhất Tuyết)", "cn": "红色的、绿色的、黑色的，你想要哪个？", "pinyin": "Hóngsè de, lǜsè de, hēisè de, nǐ xiǎng yào nǎge?"}, {"speaker": "刘小雪 (Lưu Tiểu Tuyết)", "cn": "绿色的吧。", "pinyin": "Lǜsè de ba."}, {"speaker": "王一雪 (Vương Nhất Tuyết)", "cn": "不错，我也觉得绿色的更好看。", "pinyin": "Búcuò, wǒ yě juéde lǜsè de gèng hǎokàn."}], "translation_vn": "Lưu Tiểu Tuyết: Mẹ ơi, con muốn mua cặp sách mới ạ.\nVương Nhất Tuyết: Được, đằng kia có bán cặp sách, chúng ta sang đó xem thử nhé.\nLưu Tiểu Tuyết: Bao nhiêu là cặp sách đẹp!\nVương Nhất Tuyết: Cái màu đỏ, cái màu xanh lá cây, cái màu đen, con muốn cái nào?\nLưu Tiểu Tuyết: Cái màu xanh lá cây ạ.\nVương Nhất Tuyết: Đẹp đấy, mẹ cũng thấy cặp sách màu xanh lá cây đẹp hơn.", "audio_dialogue": "4-5 @xitoytili_luoluodafang.mp3", "audio_vocab": "4-6 @xitoytili_luoluodafang.mp3"}, {"label": "Bài khóa 4", "type": "passage", "lines": [{"speaker": "", "cn": "我和妈妈去了一家商场。因为是新开的，所以这几天东西很便宜。商场里的衣服颜色很多。我没穿过红色的裤子，妈妈让我试了试，我觉得我穿红色的也很好看。", "pinyin": "Wǒ hé māma qùle yì jiā shāngchǎng. Yīnwèi shì xīn kāi de, suǒyǐ zhè jǐ tiān dōngxi hěn piányi. Shāngchǎng lǐ de yīfu yánsè hěn duō. Wǒ méi chuānguo hóngsè de kùzi, māma ràng wǒ shìle shì, wǒ juéde wǒ chuān hóngsè de yě hěn hǎokàn."}], "translation_vn": "Mình đã đi đến một trung tâm thương mại với mẹ. Vì trung tâm thương mại vừa mới khai trương, nên mấy hôm nay đồ rất rẻ. Quần áo trong trung tâm thương mại có rất nhiều màu sắc. Mình chưa từng mặc quần màu đỏ, mẹ đã bảo mình thử xem, mình nghĩ mình mặc quần màu đỏ cũng rất đẹp.", "audio_dialogue": "4-7 @xitoytili_luoluodafang.mp3", "audio_vocab": "4-8 @xitoytili_luoluodafang.mp3"}]}, {"id": 5, "title_cn": "第一次去中国朋友家", "title_pinyin": "Dì-yī cì qù Zhōngguó péngyou jiā", "title_vn": "Lần đầu đến thăm nhà bạn người Trung Quốc", "goals": ["Có thể nghe hiểu và sử dụng được bổ ngữ xu hướng để diễn đạt phương hướng của động tác.", "Nắm được cấu trúc cố định \"都……了\" để diễn đạt được ý đã làm gì hoặc đạt được điều gì.", "Hiểu về cách chào hỏi của người Trung Quốc khi gặp mặt."], "vocab": [{"hanzi": "快", "pinyin": "kuài", "pos": "phó./tt.", "vn": "mau, nhanh"}, {"hanzi": "下来", "pinyin": "xiàlái", "pos": "đgt.", "vn": "xuống, xuống dưới, xuống đây"}, {"hanzi": "上来", "pinyin": "shànglái", "pos": "đgt.", "vn": "lên, lên trên, lên đây"}, {"hanzi": "上去", "pinyin": "shàngqù", "pos": "đgt.", "vn": "lên, lên trên, lên đi"}, {"hanzi": "下面", "pinyin": "xiàmiàn", "pos": "dt.", "vn": "dưới, phía dưới"}, {"hanzi": "面", "pinyin": "miàn", "pos": "htố.", "vn": "phía"}, {"hanzi": "等", "pinyin": "děng", "pos": "đgt.", "vn": "đợi"}, {"hanzi": "一会儿", "pinyin": "yíhuìr", "pos": "sl.", "vn": "một lát"}, {"hanzi": "下去", "pinyin": "xiàqù", "pos": "đgt.", "vn": "xuống, đi xuống, xuống kia"}, {"hanzi": "进来", "pinyin": "jìnlái", "pos": "đgt.", "vn": "vào, đi vào, vào đây"}, {"hanzi": "爷爷", "pinyin": "yéye", "pos": "dt.", "vn": "ông nội"}, {"hanzi": "奶奶", "pinyin": "nǎinai", "pos": "dt.", "vn": "bà nội"}, {"hanzi": "礼物", "pinyin": "lǐwù", "pos": "dt.", "vn": "quà, quà tặng"}, {"hanzi": "准备", "pinyin": "zhǔnbèi", "pos": "đgt.", "vn": "chuẩn bị"}, {"hanzi": "奶茶", "pinyin": "nǎichá", "pos": "dt.", "vn": "trà sữa"}, {"hanzi": "跟", "pinyin": "gēn", "pos": "giới./liên.", "vn": "với, và"}, {"hanzi": "走", "pinyin": "zǒu", "pos": "đgt.", "vn": "đi bộ, đi"}, {"hanzi": "酒店", "pinyin": "jiǔdiàn", "pos": "dt.", "vn": "khách sạn"}], "grammar": [{"title": "简单趋向补语(1) - Bổ ngữ xu hướng đơn (1)", "explanation_vn": "Cấu trúc cơ bản của bổ ngữ xu hướng đơn là \"động từ + lai/khứ\". Trong đó, \"来\" biểu thị hành động di chuyển hướng về phía người nói, \"去\" biểu thị hành động di chuyển xa phía người nói, các động từ được sử dụng phổ biến nhất bao gồm \"上\", \"下\", \"进\", \"出\", \"回\" và \"过\". Ngoài ra, các động từ như \"叫、开、买、拿、请、送、要、找、走\" cũng có thể dùng trong cấu trúc này.", "examples": [{"cn": "我不上去了，就在下面等你。", "pinyin": "Wǒ bú shàngqù le, jiù zài xiàmiàn děng nǐ.", "vn": "(người nói ở dưới, người nghe ở trên)"}, {"cn": "家月到下边了，你下去接她吧。", "pinyin": "Jiāyuè dào xiàbian le, nǐ xiàqù jiē tā ba.", "vn": "(người nói ở trên, người nghe ở dưới)"}, {"cn": "我在外边呢，你出来吧。", "pinyin": "Wǒ zài wàibian ne, nǐ chūlái ba.", "vn": "(người nói ở ngoài, người nghe ở trong)"}]}, {"title": "简单趋向补语(2) - Bổ ngữ xu hướng đơn (2)", "explanation_vn": "Khi một động từ vừa mang bổ ngữ xu hướng vừa mang tân ngữ, nếu tân ngữ là danh từ chỉ địa điểm thì đặt trước \"来/去\"; nếu tân ngữ là danh từ chỉ sự vật thì có thể đặt trước hoặc sau \"来/去\". Ngoài ra, các động từ như \"开\", \"买\", \"拿\", \"请\", \"送\", \"要\", \"找\", \"走\"... cũng có thể kết hợp với các bổ ngữ xu hướng như \"上\", \"下\", \"进\", \"出\", \"回\", \"过\". Trong trường hợp này, động từ thường mang tân ngữ và đặt sau \"上, 下, 进, 出, 回, 过\".", "examples": [{"cn": "你们太客气了，还拿这么多礼物来！", "pinyin": "Nǐmen tài kèqi le, hái ná zhème duō lǐwù lái!", "vn": ""}, {"cn": "家月给我送来了一本书。", "pinyin": "Jiāyuè gěi wǒ sònglái le yì běn shū.", "vn": ""}, {"cn": "上课了，你们快进教室吧。", "pinyin": "Shàngkè le, nǐmen kuài jìn jiàoshì ba.", "vn": ""}, {"cn": "爸爸今天买回了很多水果。", "pinyin": "Bàba jīntiān mǎihuí le hěn duō shuǐguǒ.", "vn": ""}, {"cn": "妈妈拿出二十块钱，让小雪自己去买点儿吃的。", "pinyin": "Māma náchū èrshí kuài qián, ràng Xiǎoxuě zìjǐ qù mǎi diǎnr chī de.", "vn": ""}]}, {"title": "固定格式\"都……了\" - Cấu trúc cố định \"都……了\"", "explanation_vn": "Cấu trúc cố định \"都……了\" biểu thị ý đã làm gì hoặc đạt được điều gì, thường mang sắc thái nhấn mạnh hoặc không hài lòng.", "examples": [{"cn": "都12点了，我们吃饭吧。", "pinyin": "Dōu shí'èr diǎn le, wǒmen chī fàn ba.", "vn": ""}, {"cn": "都8点半了，您还不起床吗？", "pinyin": "Dōu bā diǎn bàn le, nín hái bù qǐchuáng ma?", "vn": ""}, {"cn": "我都去过北京了，不想再去了。", "pinyin": "Wǒ dōu qùguo Běijīng le, bù xiǎng zài qù le.", "vn": ""}]}], "texts": [{"label": "Bài khóa 1", "type": "dialogue", "lines": [{"speaker": "安妮 (Annie)", "cn": "家月，快下来吧，第一次去中国朋友家，别晚了。", "pinyin": "Jiāyuè, kuài xiàlái ba, dì-yī cì qù Zhōngguó péngyou jiā, bié wǎn le."}, {"speaker": "白家月 (Bạch Gia Nguyệt)", "cn": "还有时间，你上来吧。", "pinyin": "Hái yǒu shíjiān, nǐ shànglái ba."}, {"speaker": "安妮 (Annie)", "cn": "我不上去了，就在下面等你。", "pinyin": "Wǒ bú shàngqù le, jiù zài xiàmiàn děng nǐ."}, {"speaker": "白家月 (Bạch Gia Nguyệt)", "cn": "那我一会儿就下去。", "pinyin": "Nà wǒ yíhuìr jiù xiàqù."}, {"speaker": "安妮 (Annie)", "cn": "你快点儿吧。", "pinyin": "Nǐ kuài diǎnr ba."}, {"speaker": "白家月 (Bạch Gia Nguyệt)", "cn": "没事，一雪姐说11点前到就可以。", "pinyin": "Méishì, Yīxuě jiě shuō shíyī diǎn qián dào jiù kěyǐ."}], "translation_vn": "Annie: Gia Nguyệt, mau xuống nhé, lần đầu đến thăm nhà bạn người Trung Quốc, đừng đến muộn nhé.\nBạch Gia Nguyệt: Vẫn còn thời gian, bạn lên đây đi.\nAnnie: Mình không lên nữa, đợi bạn ở dưới này thôi.\nBạch Gia Nguyệt: Vậy thì một lát nữa mình sẽ xuống.\nAnnie: Bạn nhanh lên một chút nhé.\nBạch Gia Nguyệt: Không sao đâu, chị Nhất Tuyết bảo chúng ta đến trước 11 giờ là được.", "audio_dialogue": "5-1 @xitoytili_luoluodafang.mp3", "audio_vocab": "5-2 @xitoytili_luoluodafang.mp3"}, {"label": "Bài khóa 2", "type": "dialogue", "lines": [{"speaker": "王一雪 (Vương Nhất Tuyết)", "cn": "家月、安妮，快进来！我给你们介绍一下，这是孩子们的爷爷、奶奶。", "pinyin": "Jiāyuè, Ānnī, kuài jìnlái! Wǒ gěi nǐmen jièshào yíxià, zhè shì háizimen de yéye, nǎinai."}, {"speaker": "白家月、安妮 (Bạch Gia Nguyệt, Annie)", "cn": "你们好！", "pinyin": "Nǐmen hǎo!"}, {"speaker": "王一雪 (Vương Nhất Tuyết)", "cn": "爸、妈，这是白家月，这是安妮。她们都是一飞的学生。", "pinyin": "Bà, mā, zhè shì Bái Jiāyuè, zhè shì Ānnī. Tāmen dōu shì Yīfēi de xuésheng."}, {"speaker": "刘爷爷 (Ông Lưu)", "cn": "家月、安妮，你们好！", "pinyin": "Jiāyuè, Ānnī, nǐmen hǎo!"}, {"speaker": "白家月 (Bạch Gia Nguyệt)", "cn": "这是送你们的礼物。", "pinyin": "Zhè shì sòng nǐmen de lǐwù."}, {"speaker": "刘爷爷 (Ông Lưu)", "cn": "你们太客气了，还拿这么多礼物来！", "pinyin": "Nǐmen tài kèqi le, hái ná zhème duō lǐwù lái!"}, {"speaker": "白家月 (Bạch Gia Nguyệt)", "cn": "一雪姐，这是给孩子们准备的礼物。", "pinyin": "Yīxuě jiě, zhè shì gěi háizimen zhǔnbèi de lǐwù."}, {"speaker": "王一雪 (Vương Nhất Tuyết)", "cn": "谢谢！你们别客气，快坐吧！", "pinyin": "Xièxie! Nǐmen bié kèqi, kuài zuò ba!"}], "translation_vn": "Vương Nhất Tuyết: Gia Nguyệt, Annie, mau vào đi! Để chị giới thiệu một chút nhé, đây là ông nội và bà nội của các con chị.\nBạch Gia Nguyệt và Annie: Chúng cháu chào hai bác!\nVương Nhất Tuyết: Bố mẹ ơi, đây là Bạch Gia Nguyệt, còn đây là Annie. Các em ấy đều là học sinh của Nhất Phi.\nÔng Lưu: Chào Gia Nguyệt! Chào Annie!\nBạch Gia Nguyệt: Đây là chút quà chúng cháu biếu hai bác ạ.\nÔng Lưu: Các cháu thật chu đáo, còn mang nhiều quà đến như vậy.\nBạch Gia Nguyệt: Chị Nhất Tuyết, đây là quà mà chúng em chuẩn bị cho các em nhỏ.\nVương Nhất Tuyết: Cảm ơn rất nhiều! Các em đừng khách sáo, mau ngồi xuống đi!", "audio_dialogue": "5-3.mp3", "audio_vocab": "5-4 @xitoytili_luoluodafang.mp3"}, {"label": "Bài khóa 3", "type": "dialogue", "lines": [{"speaker": "王一雪 (Vương Nhất Tuyết)", "cn": "都12点了，我们吃饭吧。", "pinyin": "Dōu shí'èr diǎn le, wǒmen chī fàn ba."}, {"speaker": "白家月 (Bạch Gia Nguyệt)", "cn": "这么多好吃的，您太客气了！", "pinyin": "Zhème duō hǎochī de, nín tài kèqi le!"}, {"speaker": "王一雪 (Vương Nhất Tuyết)", "cn": "都是我自己做的，你们多吃点儿。", "pinyin": "Dōu shì wǒ zìjǐ zuò de, nǐmen duō chī diǎnr."}, {"speaker": "白家月 (Bạch Gia Nguyệt)", "cn": "奶茶也很好喝，是您自己做的吗？", "pinyin": "Nǎichá yě hěn hǎohē, shì nín zìjǐ zuò de ma?"}, {"speaker": "王一雪 (Vương Nhất Tuyết)", "cn": "不是，奶茶是爷爷买的。", "pinyin": "Bú shì, nǎichá shì yéye mǎi de."}, {"speaker": "白家月 (Bạch Gia Nguyệt)", "cn": "在哪儿买的？我还没喝过这么好喝的奶茶。", "pinyin": "Zài nǎr mǎi de? Wǒ hái méi hēguo zhème hǎohē de nǎichá."}, {"speaker": "王一雪 (Vương Nhất Tuyết)", "cn": "就在前边的商场，吃完饭你们可以跟我去看看。", "pinyin": "Jiù zài qiánbian de shāngchǎng, chīwán fàn nǐmen kěyǐ gēn wǒ qù kànkan."}], "translation_vn": "Vương Nhất Tuyết: Đã 12 giờ rồi, chúng ta ăn cơm thôi.\nBạch Gia Nguyệt: Nhiều món ngon quá ạ. Chị chu đáo quá!\nVương Nhất Tuyết: Tất cả những món này đều là chị tự tay làm đấy, em ăn nhiều một chút nhé.\nBạch Gia Nguyệt: Trà sữa cũng rất ngon. Chị tự làm à?\nVương Nhất Tuyết: Không, trà sữa là ông nội bọn em mua đấy.\nBạch Gia Nguyệt: Ông mua ở đâu vậy ạ? Em chưa từng uống trà sữa ngon như thế này.\nVương Nhất Tuyết: Ở trung tâm thương mại phía trước. Ăn xong các em có thể cùng chị đi xem.", "audio_dialogue": "5-5 @xitoytili_luoluodafang.mp3", "audio_vocab": "5-6 @xitoytili_luoluodafang.mp3"}, {"label": "Bài khóa 4", "type": "passage", "lines": [{"speaker": "", "cn": "回国前一天，我们去一雪姐家了。到她家的时候，饭菜都做好了。刘爷爷还准备了奶茶。因为吃了太多东西，我们吃完饭是走回酒店的。", "pinyin": "Huí guó qián yì tiān, wǒmen qù Yīxuě jiě jiā le. Dào tā jiā de shíhou, fàncài dōu zuòhǎo le. Liú yéye hái zhǔnbèi le nǎichá. Yīnwèi chīle tài duō dōngxi, wǒmen chīwán fàn shì zǒu huí jiǔdiàn de."}], "translation_vn": "Một ngày trước khi về nước, chúng tôi đã đi thăm nhà chị Nhất Tuyết. Khi chúng tôi đến nơi, đồ ăn đã sẵn sàng. Bác Lưu còn chuẩn bị cả trà sữa nữa. Vì ăn quá nhiều món, nên sau bữa ăn chúng tôi đã đi bộ về khách sạn.", "audio_dialogue": "5-7.mp3", "audio_vocab": "5-8.mp3"}]}, {"id": 6, "title_cn": "小雪，生日快乐！", "title_pinyin": "Xiǎoxuě, shēngrì kuàilè!", "title_vn": "Chúc mừng sinh nhật Tiểu Tuyết!", "goals": ["Có thể nghe hiểu và sử dụng được tính từ lặp lại để miêu tả tính chất hoặc trạng thái.", "Nắm vững cách dùng của cụm từ cố định \"什么的\" để diễn đạt ý liệt kê chưa đầy đủ.", "Nắm vững cách dùng của trợ từ kết cấu \"地\" để miêu tả cách thức hoặc trạng thái của hành động.", "Hiểu về cách người Trung Quốc tổ chức sinh nhật."], "vocab": [{"hanzi": "生日", "pinyin": "shēngrì", "pos": "dt.", "vn": "sinh nhật"}, {"hanzi": "忘", "pinyin": "wàng", "pos": "đgt.", "vn": "quên"}, {"hanzi": "画", "pinyin": "huà", "pos": "đgt./dt.", "vn": "vẽ, tranh"}, {"hanzi": "画笔", "pinyin": "huàbǐ", "pos": "dt.", "vn": "bút màu, bút vẽ"}, {"hanzi": "蛋糕", "pinyin": "dàngāo", "pos": "dt.", "vn": "bánh kem, bánh ga tô"}, {"hanzi": "快乐", "pinyin": "kuàilè", "pos": "tt.", "vn": "vui vẻ"}, {"hanzi": "打开", "pinyin": "dǎkāi", "pos": "đgt.", "vn": "mở ra, bóc ra"}, {"hanzi": "长", "pinyin": "cháng", "pos": "tt.", "vn": "dài"}, {"hanzi": "鱼", "pinyin": "yú", "pos": "dt.", "vn": "cá"}, {"hanzi": "肉", "pinyin": "ròu", "pos": "dt.", "vn": "thịt"}, {"hanzi": "过", "pinyin": "guò", "pos": "đgt.", "vn": "trải qua, đón (sinh nhật)"}, {"hanzi": "地", "pinyin": "de", "pos": "trợ.", "vn": "dùng để nối trạng ngữ với động từ"}, {"hanzi": "床", "pinyin": "chuáng", "pos": "dt.", "vn": "giường"}, {"hanzi": "舒服", "pinyin": "shūfu", "pos": "tt.", "vn": "thoải mái, dễ chịu"}], "grammar": [{"title": "形容词重叠 - Tính từ lặp lại", "explanation_vn": "Hình thức lặp lại của tính từ đơn âm tiết \"A\" là \"AA\", hình thức lặp lại của tính từ song âm tiết \"AB\" là \"AABB\". Tính từ lặp lại dùng để biểu thị mức độ cao hoặc tình cảm yêu thích, thân mật.", "examples": [{"cn": "我再给她买个大大的生日蛋糕。", "pinyin": "Wǒ zài gěi tā mǎi ge dàdà de shēngrì dàngāo.", "vn": ""}, {"cn": "这只猫小小的，真让人喜欢。", "pinyin": "Zhè zhī māo xiǎoxiǎo de, zhēn ràng rén xǐhuan.", "vn": ""}, {"cn": "一雪的女儿每天都漂漂亮亮的。", "pinyin": "Yīxuě de nǚ'ér měitiān dōu piàopiàoliàngliàng de.", "vn": ""}]}, {"title": "固定短语\"什么的\" - Cụm từ cố định \"什么的\"", "explanation_vn": "Cụm từ cố định \"什么的\" có ý nghĩa là \"vân vân (...)\". Cấu trúc cơ bản: ……什么的.", "examples": [{"cn": "画我们的家！有爸爸、妈妈、弟弟，还有黑色的狗，白色的猫什么的。", "pinyin": "Huà wǒmen de jiā! Yǒu bàba, māma, dìdi, hái yǒu hēisè de gǒu, báisè de māo shénmede.", "vn": ""}, {"cn": "桌子上有电脑、杯子、书和画笔什么的。", "pinyin": "Zhuōzi shang yǒu diànnǎo, bēizi, shū hé huàbǐ shénmede.", "vn": ""}, {"cn": "她拿来了一些水、面包和苹果什么的。", "pinyin": "Tā nálái le yìxiē shuǐ, miànbāo hé píngguǒ shénmede.", "vn": ""}]}, {"title": "结构助词\"地\" - Trợ từ kết cấu \"地\"", "explanation_vn": "Trợ từ kết cấu \"地\" thường đặt giữa tính từ và động từ để biểu thị cách thức hoặc trạng thái của hành động.", "examples": [{"cn": "过生日就要吃好吃的，还要高高兴兴地玩。", "pinyin": "Guò shēngrì jiù yào chī hǎochī de, hái yào gāogāoxìngxìng de wán.", "vn": ""}, {"cn": "老师早早地到了教室。", "pinyin": "Lǎoshī zǎozǎo de dàole jiàoshì.", "vn": ""}, {"cn": "爸爸很快地吃完早饭，就去上班了。", "pinyin": "Bàba hěn kuài de chīwán zǎofàn, jiù qù shàngbān le.", "vn": ""}]}], "texts": [{"label": "Bài khóa 1", "type": "dialogue", "lines": [{"speaker": "王一雪 (Vương Nhất Tuyết)", "cn": "明天就是女儿的生日了。", "pinyin": "Míngtiān jiù shì nǚ'ér de shēngrì le."}, {"speaker": "刘明 (Lưu Minh)", "cn": "你不说，我还真忘了。我们给她准备个什么礼物呢？", "pinyin": "Nǐ bù shuō, wǒ hái zhēn wàng le. Wǒmen gěi tā zhǔnbèi ge shénme lǐwù ne?"}, {"speaker": "王一雪 (Vương Nhất Tuyết)", "cn": "她喜欢画画，你觉得画笔怎么样？", "pinyin": "Tā xǐhuan huàhuà, nǐ juéde huàbǐ zěnmeyàng?"}, {"speaker": "刘明 (Lưu Minh)", "cn": "就送画笔吧！", "pinyin": "Jiù sòng huàbǐ ba!"}, {"speaker": "王一雪 (Vương Nhất Tuyết)", "cn": "那我明天上午就去买。", "pinyin": "Nà wǒ míngtiān shàngwǔ jiù qù mǎi."}, {"speaker": "刘明 (Lưu Minh)", "cn": "好的！我再给她买个大大的生日蛋糕。", "pinyin": "Hǎo de! Wǒ zài gěi tā mǎi ge dàdà de shēngrì dàngāo."}], "translation_vn": "Vương Nhất Tuyết: Ngày mai là sinh nhật con gái rồi.\nLưu Minh: Nếu em không nhắc thì anh đã quên mất rồi. Chúng ta nên chuẩn bị quà gì cho con nhỉ?\nVương Nhất Tuyết: Con thích vẽ tranh. Anh thấy tặng con bút vẽ màu có được không?\nLưu Minh: Thế thì tặng bút màu nhé!\nVương Nhất Tuyết: Vậy thì sáng mai em sẽ đi mua.\nLưu Minh: Được! Anh cũng sẽ mua thêm cho con một chiếc bánh sinh nhật to.", "audio_dialogue": "6-1.mp3", "audio_vocab": "6-2.mp3"}, {"label": "Bài khóa 2", "type": "dialogue", "lines": [{"speaker": "刘明 (Lưu Minh)", "cn": "小雪，生日快乐！", "pinyin": "Xiǎoxuě, shēngrì kuàilè!"}, {"speaker": "刘小明 (Lưu Tiểu Minh)", "cn": "姐姐，生日快乐！", "pinyin": "Jiějie, shēngrì kuàilè!"}, {"speaker": "王一雪 (Vương Nhất Tuyết)", "cn": "小雪，这是爸爸、妈妈送你的礼物。", "pinyin": "Xiǎoxuě, zhè shì bàba, māma sòng nǐ de lǐwù."}, {"speaker": "刘明 (Lưu Minh)", "cn": "你打开看看喜欢不喜欢。", "pinyin": "Nǐ dǎkāi kànkan xǐhuan bu xǐhuan."}, {"speaker": "刘小雪 (Lưu Tiểu Tuyết)", "cn": "画笔！我很喜欢！", "pinyin": "Huàbǐ! Wǒ hěn xǐhuan!"}, {"speaker": "王一雪 (Vương Nhất Tuyết)", "cn": "那你想画点儿什么？", "pinyin": "Nà nǐ xiǎng huà diǎnr shénme?"}, {"speaker": "刘小雪 (Lưu Tiểu Tuyết)", "cn": "画我们的家！有爸爸、妈妈、弟弟，还有黑色的狗，白色的猫什么的。", "pinyin": "Huà wǒmen de jiā! Yǒu bàba, māma, dìdi, hái yǒu hēisè de gǒu, báisè de māo shénmede."}, {"speaker": "刘小明 (Lưu Tiểu Minh)", "cn": "那我要画一个穿白色衣服的姐姐。", "pinyin": "Nà wǒ yào huà yí ge chuān báisè yīfu de jiějie."}], "translation_vn": "Lưu Minh: Chúc mừng sinh nhật Tiểu Tuyết!\nLưu Tiểu Minh: Chúc mừng sinh nhật chị!\nVương Nhất Tuyết: Tiểu Tuyết, đây là quà bố mẹ tặng con.\nLưu Minh: Con mở ra xem có thích không.\nLưu Tiểu Tuyết: Bút vẽ à, con rất thích ạ!\nVương Nhất Tuyết: Thế con muốn vẽ gì đây?\nLưu Tiểu Tuyết: Vẽ cả gia đình mình. Có bố, mẹ, em trai, có thêm con chó màu đen, con mèo trắng...\nLưu Tiểu Minh: Vậy em muốn vẽ một chị gái mặc quần áo màu trắng.", "audio_dialogue": "6-3.mp3", "audio_vocab": "6-4.mp3"}, {"label": "Bài khóa 3", "type": "dialogue", "lines": [{"speaker": "刘明 (Lưu Minh)", "cn": "小雪，看看今天有什么好吃的。", "pinyin": "Xiǎoxuě, kànkan jīntiān yǒu shénme hǎochī de."}, {"speaker": "刘小雪 (Lưu Tiểu Tuyết)", "cn": "长长的面条儿，大大的蛋糕。", "pinyin": "Chángcháng de miàntiáor, dàdà de dàngāo."}, {"speaker": "刘明 (Lưu Minh)", "cn": "你看，还有鱼啊肉啊什么的，都是你喜欢吃的。", "pinyin": "Nǐ kàn, hái yǒu yú a ròu a shénmede, dōu shì nǐ xǐhuan chī de."}, {"speaker": "刘小雪 (Lưu Tiểu Tuyết)", "cn": "谢谢爸爸、妈妈！", "pinyin": "Xièxie bàba, māma!"}, {"speaker": "王一雪 (Vương Nhất Tuyết)", "cn": "快去叫弟弟过来吃饭吧，吃完饭我们还要出去玩呢。", "pinyin": "Kuài qù jiào dìdi guòlái chī fàn ba, chīwán fàn wǒmen hái yào chūqù wán ne."}, {"speaker": "刘小雪 (Lưu Tiểu Tuyết)", "cn": "过生日真好啊！", "pinyin": "Guò shēngrì zhēn hǎo a!"}, {"speaker": "王一雪 (Vương Nhất Tuyết)", "cn": "是的，过生日就要吃好吃的，还要高高兴兴地玩。", "pinyin": "Shì de, guò shēngrì jiù yào chī hǎochī de, hái yào gāogāoxìngxìng de wán."}], "translation_vn": "Lưu Minh: Tiểu Tuyết, con nhìn xem hôm nay có những món gì ngon nào.\nLưu Tiểu Tuyết: Mì sợi dài và chiếc bánh ga tô lớn.\nLưu Minh: Con nhìn xem, còn có cá, thịt và những món khác nữa. Tất cả đều là những món con thích ăn.\nLưu Tiểu Tuyết: Cảm ơn bố mẹ ạ!\nVương Nhất Tuyết: Mau gọi em trai con ra ăn cơm đi. Ăn xong chúng ta sẽ đi chơi nhé.\nLưu Tiểu Tuyết: Sinh nhật thật tuyệt!\nVương Nhất Tuyết: Đúng vậy, sinh nhật thì phải ăn món ngon, còn phải chơi vui nữa.", "audio_dialogue": "6-5.mp3", "audio_vocab": "6-6.mp3"}, {"label": "Bài khóa 4", "type": "passage", "lines": [{"speaker": "", "cn": "今天是女儿的生日。我们买了蛋糕，做了面条儿，还做了鱼啊肉啊什么的。吃完晚饭，一家人去看了个电影。回家后，孩子们早早地就上床了。明天不上学，他们说要舒舒服服地睡一觉，让我们晚点儿叫他们起床。这是很忙，很累，但很快乐的一天。", "pinyin": "Jīntiān shì nǚ'ér de shēngrì. Wǒmen mǎile dàngāo, zuòle miàntiáor, hái zuòle yú a ròu a shénmede. Chīwán wǎnfàn, yì jiā rén qù kànle gè diànyǐng. Huí jiā hòu, háizimen zǎozǎo de jiù shàng chuáng le. Míngtiān bú shàngxué, tāmen shuō yào shūshūfúfú de shuì yí jiào, ràng wǒmen wǎn diǎnr jiào tāmen qǐchuáng. Zhè shì hěn máng, hěn lèi, dàn hěn kuàilè de yì tiān."}], "translation_vn": "Hôm nay là sinh nhật con gái. Chúng tôi đã mua một chiếc bánh ga tô, nấu mì sợi, còn làm các món như cá, thịt... Sau khi ăn tối xong, cả gia đình chúng tôi đã đi xem phim. Sau khi về nhà, bọn trẻ đi ngủ sớm. Ngày mai không phải đi học, chúng nói muốn ngủ một giấc thật thoải mái, bảo chúng tôi gọi chúng dậy muộn hơn một chút. Hôm nay là một ngày rất bận rộn và rất mệt, nhưng cũng là một ngày rất vui.", "audio_dialogue": "6-7.mp3", "audio_vocab": "6-8.mp3"}]}, {"id": 7, "title_cn": "他篮球打得很好", "title_pinyin": "Tā lánqiú dǎ de hěn hǎo", "title_vn": "Bạn ấy chơi bóng rổ rất hay", "goals": ["能听懂并描述动作进行的状态。Có thể nghe hiểu và miêu tả được trạng thái của hành động đang diễn ra.", "掌握紧缩复句 \"一……就……\" 的用法，能表达动作接连发生的意思。Nắm vững cách dùng của câu ghép rút gọn \"一……就……\" để diễn đạt các hành động xảy ra liên tiếp.", "能谈论常做的运动。Có thể nói về những môn thể thao thường tập luyện."], "vocab": [{"hanzi": "从", "pinyin": "cóng", "pos": "giới.", "vn": "từ"}, {"hanzi": "往", "pinyin": "wǎng", "pos": "giới./dgt.", "vn": "hướng tới, đi đến, về phía"}, {"hanzi": "跑", "pinyin": "pǎo", "pos": "dgt.", "vn": "chạy"}, {"hanzi": "打", "pinyin": "dǎ", "pos": "dgt.", "vn": "đánh, chơi (thể thao)"}, {"hanzi": "篮球", "pinyin": "lánqiú", "pos": "dt.", "vn": "bóng rổ"}, {"hanzi": "运动", "pinyin": "yùndòng", "pos": "dt./dgt.", "vn": "thể thao, môn thể thao, vận động, tập thể dục..."}, {"hanzi": "踢", "pinyin": "tī", "pos": "dgt.", "vn": "đá"}, {"hanzi": "足球", "pinyin": "zúqiú", "pos": "dt.", "vn": "bóng đá"}, {"hanzi": "球", "pinyin": "qiú", "pos": "dt.", "vn": "quả bóng"}, {"hanzi": "得", "pinyin": "de", "pos": "trợ.", "vn": "dùng giữa động từ/tính từ và bổ ngữ kết quả/trình độ"}, {"hanzi": "跑步", "pinyin": "pǎobù", "pos": "dgt.", "vn": "chạy bộ"}, {"hanzi": "游泳", "pinyin": "yóuyǒng", "pos": "dgt.", "vn": "bơi, bơi lội"}, {"hanzi": "游", "pinyin": "yóu", "pos": "dgt.", "vn": "bơi, bơi lội"}, {"hanzi": "爱好", "pinyin": "àihào", "pos": "dt./dgt.", "vn": "sở thích, thích"}, {"hanzi": "开始", "pinyin": "kāishǐ", "pos": "dgt./dt.", "vn": "bắt đầu, lúc đầu"}], "grammar": [{"title": "紧缩复句 \"一……就……\" (Câu ghép rút gọn \"一……就……\")", "explanation_vn": "Câu ghép rút gọn \"一……就……\" biểu thị hành động thứ hai xảy ra ngay sau hành động thứ nhất; đồng thời cũng thể hiện hành động thứ nhất là điều kiện hoặc nguyên nhân, còn hành động thứ hai là kết quả. Khi chủ ngữ giống nhau, chủ ngữ được đặt trước \"一\" hoặc \"就\"; khi chủ ngữ khác nhau, hai chủ ngữ lần lượt đứng trước \"一\" và \"就\".", "examples": [{"cn": "你怎么一下课就往外跑？", "pinyin": "Nǐ zěnme yī xiàkè jiù wǎng wài pǎo?", "vn": ""}, {"cn": "我一到家，妈妈就打电话了。", "pinyin": "Wǒ yī dào jiā, māma jiù dǎ diànhuà le.", "vn": ""}, {"cn": "一到星期六，陈天中就跟同学去打篮球。", "pinyin": "Yī dào xīngqīliù, Chén Tiānzhōng jiù gēn tóngxué qù dǎ lánqiú.", "vn": ""}]}, {"title": "状态补语 (1) (Bổ ngữ trạng thái (1))", "explanation_vn": "Bổ ngữ trạng thái dùng sau động từ, để nói rõ thêm trạng thái của hành động. Cấu trúc cơ bản: động từ + 得 + cụm tính từ. Hình thức phủ định là thêm \"不\" trước tính từ. Hình thức nghi vấn có ba cách: (1) thêm \"吗\" ở cuối câu; (2) động từ + 得 + tính từ + 不 + tính từ; (3) động từ + 得 + 怎么样.", "examples": [{"cn": "我踢得还可以。", "pinyin": "Wǒ tī de hái kěyǐ.", "vn": ""}, {"cn": "他们打得很高兴。", "pinyin": "Tāmen dǎ de hěn gāoxìng.", "vn": ""}, {"cn": "白家月跑得不快。", "pinyin": "Bái Jiāyuè pǎo de bú kuài.", "vn": ""}, {"cn": "你跑得快吗？", "pinyin": "Nǐ pǎo de kuài ma?", "vn": ""}, {"cn": "他跑得早不早？", "pinyin": "Tā pǎo de zǎo bu zǎo?", "vn": ""}, {"cn": "他们跑得怎么样？", "pinyin": "Tāmen pǎo de zěnmeyàng?", "vn": ""}]}, {"title": "状态补语 (2) (Bổ ngữ trạng thái (2))", "explanation_vn": "Trong câu có bổ ngữ trạng thái, nếu động từ là từ li hợp, cần lặp lại từ tố có tính chất động từ. Nếu động từ có tân ngữ, có thể đảo tân ngữ lên trước động từ hoặc lặp lại động từ.", "examples": [{"cn": "我游泳游得不快。", "pinyin": "Wǒ yóuyǒng yóu de bú kuài.", "vn": ""}, {"cn": "你篮球打得怎么样？", "pinyin": "Nǐ lánqiú dǎ de zěnmeyàng?", "vn": ""}, {"cn": "白家月写汉字写得很好看。", "pinyin": "Bái Jiāyuè xiě Hànzì xiě de hěn hǎokàn.", "vn": ""}]}], "texts": [{"label": "Bài khóa 1", "type": "dialogue", "lines": [{"speaker": "Chén Tiānzhōng (陈天中)", "cn": "安妮，你是什么时候从北京回来的？", "pinyin": "Ānnī, nǐ shì shénme shíhou cóng Běijīng huílái de?"}, {"speaker": "Annie (安妮)", "cn": "昨天下午。天中，你怎么一下课就往外跑？", "pinyin": "Zuótiān xiàwǔ. Tiānzhōng, nǐ zěnme yī xiàkè jiù wǎng wài pǎo?"}, {"speaker": "Chén Tiānzhōng (陈天中)", "cn": "我跟同学说好了，一起去打篮球。", "pinyin": "Wǒ gēn tóngxué shuōhǎo le, yìqǐ qù dǎ lánqiú."}, {"speaker": "Annie (安妮)", "cn": "我也想跟你们一起玩。", "pinyin": "Wǒ yě xiǎng gēn nǐmen yìqǐ wán."}, {"speaker": "Chén Tiānzhōng (陈天中)", "cn": "没问题，走吧。", "pinyin": "Méi wèntí, zǒu ba."}], "translation_vn": "Trần Thiên Trung: Annie, bạn từ Bắc Kinh về khi nào vậy?\nAnnie: Chiều hôm qua. Thiên Trung, sao vừa mới tan học là bạn chạy ra ngoài ngay vậy?\nTrần Thiên Trung: Mình đã hẹn với các bạn cùng đi chơi bóng rổ.\nAnnie: Mình cũng muốn chơi cùng các bạn.\nTrần Thiên Trung: Không vấn đề gì, đi thôi!", "audio_dialogue": "7-1.mp3", "audio_vocab": "7-2 @xitoytili_luoluodafang.mp3"}, {"label": "Bài khóa 2", "type": "dialogue", "lines": [{"speaker": "Annie (安妮)", "cn": "天中，你是不是很喜欢打篮球？", "pinyin": "Tiānzhōng, nǐ shì bu shì hěn xǐhuan dǎ lánqiú?"}, {"speaker": "Chén Tiānzhōng (陈天中)", "cn": "没错。", "pinyin": "Méi cuò."}, {"speaker": "Annie (安妮)", "cn": "你还喜欢什么运动？", "pinyin": "Nǐ hái xǐhuan shénme yùndòng?"}, {"speaker": "Chén Tiānzhōng (陈天中)", "cn": "我还喜欢踢足球，一到星期天就跟朋友们去踢球。", "pinyin": "Wǒ hái xǐhuan tī zúqiú, yī dào xīngqītiān jiù gēn péngyoumen qù tī qiú."}, {"speaker": "Annie (安妮)", "cn": "你踢得怎么样？", "pinyin": "Nǐ tī de zěnmeyàng?"}, {"speaker": "Chén Tiānzhōng (陈天中)", "cn": "我踢得还可以。", "pinyin": "Wǒ tī de hái kěyǐ."}], "translation_vn": "Annie: Thiên Trung, có phải bạn rất thích chơi bóng rổ không?\nTrần Thiên Trung: Đúng vậy.\nAnnie: Bạn còn thích môn thể thao nào khác?\nTrần Thiên Trung: Mình còn thích chơi bóng đá nữa, cứ đến Chủ nhật mình lại đi đá bóng cùng bạn bè.\nAnnie: Bạn chơi có tốt không?\nTrần Thiên Trung: Mình chơi cũng tàm tạm.", "audio_dialogue": "7-3 @xitoytili_luoluodafang.mp3", "audio_vocab": "7-4 @xitoytili_luoluodafang.mp3"}, {"label": "Bài khóa 3", "type": "dialogue", "lines": [{"speaker": "Chén Tiānzhōng (陈天中)", "cn": "你篮球打得怎么样？", "pinyin": "Nǐ lánqiú dǎ de zěnmeyàng?"}, {"speaker": "Annie (安妮)", "cn": "打得还可以！", "pinyin": "Dǎ de hái kěyǐ!"}, {"speaker": "Chén Tiānzhōng (陈天中)", "cn": "跑步呢？你跑步快不快？", "pinyin": "Pǎobù ne? Nǐ pǎobù kuài bu kuài?"}, {"speaker": "Annie (安妮)", "cn": "我跑得不快，也不太喜欢跑步。", "pinyin": "Wǒ pǎo de bú kuài, yě bú tài xǐhuan pǎobù."}, {"speaker": "Chén Tiānzhōng (陈天中)", "cn": "那你喜欢游泳吗？", "pinyin": "Nà nǐ xǐhuan yóuyǒng ma?"}, {"speaker": "Annie (安妮)", "cn": "喜欢，但我游泳游得不快。", "pinyin": "Xǐhuan, dàn wǒ yóuyǒng yóu de bú kuài."}], "translation_vn": "Trần Thiên Trung: Bạn chơi bóng rổ thế nào?\nAnnie: Chơi cũng tàm tạm.\nTrần Thiên Trung: Còn chạy bộ thì sao? Bạn chạy có nhanh không?\nAnnie: Mình chạy không nhanh, mình cũng không thích chạy bộ lắm.\nTrần Thiên Trung: Vậy bạn có thích bơi không?\nAnnie: Có, nhưng mình bơi không nhanh lắm.", "audio_dialogue": "7-5 @xitoytili_luoluodafang.mp3", "audio_vocab": "7-6 @xitoytili_luoluodafang.mp3"}, {"label": "Bài khóa 4", "type": "passage", "lines": [{"speaker": "", "cn": "我的爱好是运动。从上小学开始，我每天都跟爸爸去运动。现在我篮球打得很好，足球踢得不错，游泳游得也很快。我一有时间就去运动。", "pinyin": "Wǒ de àihào shì yùndòng. Cóng shàng xiǎoxué kāishǐ, wǒ měitiān dōu gēn bàba qù yùndòng. Xiànzài wǒ lánqiú dǎ de hěn hǎo, zúqiú tī de búcuò, yóuyǒng yóu de yě hěn kuài. Wǒ yī yǒu shíjiān jiù qù yùndòng."}], "translation_vn": "Sở thích của tôi là thể thao. Bắt đầu từ khi học tiểu học, ngày nào tôi cũng tập thể dục cùng bố. Bây giờ tôi chơi bóng rổ rất giỏi, chơi bóng đá khá tốt, bơi cũng rất nhanh. Hễ có thời gian là tôi đi chơi thể thao.", "audio_dialogue": "7-7 @xitoytili_luoluodafang.mp3", "audio_vocab": "7-8 @xitoytili_luoluodafang.mp3"}]}, {"id": 8, "title_cn": "虽然你忘了，但是我记得", "title_pinyin": "Suīrán nǐ wàng le, dànshì wǒ jìde", "title_vn": "Mặc dù em quên, nhưng anh vẫn nhớ", "goals": ["能听懂并谈论生日的庆祝活动。Có thể nghe hiểu và nói được các hoạt động chúc mừng sinh nhật.", "能听懂并使用\"比\"描述事物之间的差别。Có thể nghe hiểu và sử dụng được \"比\" để miêu tả sự khác biệt giữa các sự vật.", "掌握转折复句 \"虽然……，但是……\" 的用法，能表达语义的转折。Nắm vững cách dùng của câu ghép chuyển ý \"虽然……，但是……\" để diễn đạt quan hệ ý nghĩa chuyển ý.", "了解中国人对一些数字的喜好。Hiểu về sở thích của người Trung Quốc với một số con số nhất định."], "vocab": [{"hanzi": "手表", "pinyin": "shǒubiǎo", "pos": "dt.", "vn": "đồng hồ đeo tay"}, {"hanzi": "左边", "pinyin": "zuǒbian", "pos": "dt.", "vn": "bên trái"}, {"hanzi": "左", "pinyin": "zuǒ", "pos": "dt.", "vn": "trái"}, {"hanzi": "比", "pinyin": "bǐ", "pos": "giới./dgt.", "vn": "so, so với, hơn (so sánh)"}, {"hanzi": "右边", "pinyin": "yòubian", "pos": "dt.", "vn": "bên phải"}, {"hanzi": "右", "pinyin": "yòu", "pos": "dt.", "vn": "phải"}, {"hanzi": "记得", "pinyin": "jìde", "pos": "dgt.", "vn": "nhớ, nhớ ra"}, {"hanzi": "爱情片", "pinyin": "àiqíngpiàn", "pos": "dt.", "vn": "phim tình cảm"}, {"hanzi": "有意思", "pinyin": "yǒuyìsi", "pos": "", "vn": "hay, thú vị"}, {"hanzi": "点", "pinyin": "diǎn", "pos": "dgt.", "vn": "gọi, chọn (món)"}, {"hanzi": "虽然", "pinyin": "suīrán", "pos": "liên.", "vn": "mặc dù, tuy"}, {"hanzi": "但是", "pinyin": "dànshì", "pos": "liên.", "vn": "nhưng"}, {"hanzi": "花", "pinyin": "huā", "pos": "dgt.", "vn": "tiêu, chi tiêu"}, {"hanzi": "妻子", "pinyin": "qīzi", "pos": "dt.", "vn": "vợ"}, {"hanzi": "丈夫", "pinyin": "zhàngfū", "pos": "dt.", "vn": "chồng"}, {"hanzi": "饭馆", "pinyin": "fànguǎn", "pos": "dt.", "vn": "nhà hàng, quán ăn"}], "grammar": [{"title": "比较句 (1) (Câu so sánh (1))", "explanation_vn": "Trong bài này, chúng ta học cách dùng giới từ \"比\" để so sánh sự khác biệt về tính chất và trạng thái của sự vật. Cấu trúc cơ bản: A 比 B + tính từ/cụm tính từ.", "examples": [{"cn": "我也觉得左边的比右边的好看。", "pinyin": "Wǒ yě juéde zuǒbian de bǐ yòubian de hǎokàn.", "vn": ""}, {"cn": "今天比昨天冷。", "pinyin": "Jīntiān bǐ zuótiān lěng.", "vn": ""}, {"cn": "他觉得篮球比足球有意思。", "pinyin": "Tā juéde lánqiú bǐ zúqiú yǒu yìsi.", "vn": ""}]}, {"title": "比较句 (2) (Câu so sánh (2))", "explanation_vn": "Trong câu so sánh dùng \"比\", không thể thêm phó từ chỉ mức độ như \"很\", \"非常\" vào trước tính từ, có thể thêm \"还\" và \"更\" để chỉ mức độ cao hơn.", "examples": [{"cn": "我看网上说这个电影比那个爱情片更有意思。（爱情片很有意思，这个电影更有意思）", "pinyin": "Wǒ kàn wǎngshang shuō zhège diànyǐng bǐ nàge àiqíngpiàn gèng yǒu yìsi. (Àiqíngpiàn hěn yǒu yìsi, zhège diànyǐng gèng yǒu yìsi.)", "vn": ""}, {"cn": "今天比昨天更热。（昨天很热，今天更热）", "pinyin": "Jīntiān bǐ zuótiān gèng rè. (Zuótiān hěn rè, jīntiān gèng rè.)", "vn": ""}, {"cn": "我觉得奶茶比牛奶还好喝。（我觉得牛奶很好喝，奶茶更好喝）", "pinyin": "Wǒ juéde nǎichá bǐ niúnǎi hái hǎohē. (Wǒ juéde niúnǎi hěn hǎohē, nǎichá gèng hǎohē.)", "vn": ""}]}, {"title": "转折复句 \"虽然……，但是……\" (Câu ghép chuyển ý \"虽然……，但是……\")", "explanation_vn": "Câu ghép chuyển ý được tạo bởi cấu trúc \"虽然……，但是……\". \"虽然\" và \"但是\" có thể sử dụng thành cặp, cũng có thể lược bớt một trong hai từ này.", "examples": [{"cn": "虽然你忘了，但是我记得。", "pinyin": "Suīrán nǐ wàng le, dànshì wǒ jìde.", "vn": ""}, {"cn": "外边下雪了，但是不太冷。", "pinyin": "Wàibian xiàxuě le, dànshì bú tài lěng.", "vn": ""}, {"cn": "虽然觉得有点儿累，我还是走回家了。", "pinyin": "Suīrán juéde yǒudiǎnr lèi, wǒ háishi zǒu huí jiā le.", "vn": ""}]}], "texts": [{"label": "Bài khóa 1", "type": "dialogue", "lines": [{"speaker": "Wáng Yīxuě (王一雪)", "cn": "你看，这两块手表怎么样？", "pinyin": "Nǐ kàn, zhè liǎng kuài shǒubiǎo zěnmeyàng?"}, {"speaker": "Liú Míng (刘明)", "cn": "都不错！", "pinyin": "Dōu búcuò!"}, {"speaker": "Wáng Yīxuě (王一雪)", "cn": "我喜欢左边的这个。", "pinyin": "Wǒ xǐhuan zuǒbian de zhège."}, {"speaker": "Liú Míng (刘明)", "cn": "我也觉得左边的比右边的好看。", "pinyin": "Wǒ yě juéde zuǒbian de bǐ yòubian de hǎokàn."}, {"speaker": "Wáng Yīxuě (王一雪)", "cn": "你知道要多少钱？", "pinyin": "Nǐ zhīdào yào duōshao qián?"}, {"speaker": "Liú Míng (刘明)", "cn": "真不便宜！八千八！", "pinyin": "Zhēn bù piányi! Bāqiān bā!"}], "translation_vn": "Vương Nhất Tuyết: Anh nhìn này, hai chiếc đồng hồ này thế nào?\nLưu Minh: Đều rất đẹp!\nVương Nhất Tuyết: Em thích chiếc bên trái.\nLưu Minh: Anh cũng thấy chiếc bên trái đẹp hơn chiếc bên phải.\nVương Nhất Tuyết: Anh nhìn xem bao nhiêu tiền!\nLưu Minh: Thật không rẻ! 8800 đồng!", "audio_dialogue": "8-1 @xitoytili_luoluodafang.mp3", "audio_vocab": "8-2 @xitoytili_luoluodafang.mp3"}, {"label": "Bài khóa 2", "type": "dialogue", "lines": [{"speaker": "Liú Míng (刘明)", "cn": "今天有不少电影，我们看个电影吧。", "pinyin": "Jīntiān yǒu bù shǎo diànyǐng, wǒmen kàn gè diànyǐng ba."}, {"speaker": "Wáng Yīxuě (王一雪)", "cn": "好啊！我们看哪个？", "pinyin": "Hǎo a! Wǒmen kàn nǎge?"}, {"speaker": "Liú Míng (刘明)", "cn": "我记得你喜欢看爱情片，我们看那个爱情片，怎么样？", "pinyin": "Wǒ jìde nǐ xǐhuan kàn àiqíngpiàn, wǒmen kàn nàge àiqíngpiàn, zěnmeyàng?"}, {"speaker": "Wáng Yīxuě (王一雪)", "cn": "还是看这个吧，我看网上说这个电影比那个爱情片更有意思。", "pinyin": "Háishì kàn zhège ba, wǒ kàn wǎngshang shuō zhège diànyǐng bǐ nàge àiqíngpiàn gèng yǒu yìsi."}, {"speaker": "Liú Míng (刘明)", "cn": "好。我去买票。", "pinyin": "Hǎo. Wǒ qù mǎi piào."}, {"speaker": "Wáng Yīxuě (王一雪)", "cn": "到网上买吧，网上买比在这里买便宜。", "pinyin": "Dào wǎngshang mǎi ba, wǎngshang mǎi bǐ zài zhèlǐ mǎi piányi."}], "translation_vn": "Lưu Minh: Hôm nay có rất nhiều phim, chúng ta đi xem phim nhé.\nVương Nhất Tuyết: Hay quá! Chúng ta xem phim nào?\nLưu Minh: Anh nhớ là em thích xem phim tình cảm, hay chúng ta xem bộ phim tình cảm kia, được không?\nVương Nhất Tuyết: Xem bộ phim này đi, em thấy trên mạng nói bộ phim này hay hơn bộ phim tình cảm đó.\nLưu Minh: Được, anh đi mua vé.\nVương Nhất Tuyết: Mua trên mạng đi à, mua trên mạng rẻ hơn mua ở đây.", "audio_dialogue": "8-3 @xitoytili_luoluodafang.mp3", "audio_vocab": "8-4 @xitoytili_luoluodafang.mp3"}, {"label": "Bài khóa 3", "type": "dialogue", "lines": [{"speaker": "Liú Míng (刘明)", "cn": "您好！就要这几个菜吧，谢谢！", "pinyin": "Nínhǎo! Jiù yào zhè jǐ gè cài ba, xièxiè!"}, {"speaker": "Wáng Yīxuě (王一雪)", "cn": "怎么点这么多菜？", "pinyin": "Zěnme diǎn zhème duō cài?"}, {"speaker": "Liú Míng (刘明)", "cn": "你想想，今天是几月几号？", "pinyin": "Nǐ xiǎngxiang, jīntiān shì jǐ yuè jǐ hào?"}, {"speaker": "Wáng Yīxuě (王一雪)", "cn": "8月27号。啊！我的生日！", "pinyin": "Bā yuè èrshíqī hào. À! Wǒ de shēngrì!"}, {"speaker": "Liú Míng (刘明)", "cn": "生日快乐！虽然你忘了，但是我记得。看看这是什么？", "pinyin": "Shēngrì kuàilè! Suīrán nǐ wàng le, dànshì wǒ jìde. Kànkan zhè shì shénme?"}, {"speaker": "Wáng Yīxuě (王一雪)", "cn": "手表！吃饭、看电影、买手表，今天花了不少钱吧？", "pinyin": "Shǒubiǎo! Chī fàn, kàn diànyǐng, mǎi shǒubiǎo, jīntiān huāle bù shǎo qián ba?"}, {"speaker": "Liú Míng (刘明)", "cn": "虽然花了一些钱，但是我们过了一个快乐的生日。", "pinyin": "Suīrán huāle yìxiē qián, dànshì wǒmen guòle yí gè kuàilè de shēngrì."}], "translation_vn": "Lưu Minh: Chào chị! Chúng tôi sẽ gọi những món này thôi, cảm ơn!\nVương Nhất Tuyết: Sao anh gọi nhiều thế?\nLưu Minh: Em nghĩ xem, hôm nay là ngày mấy tháng mấy?\nVương Nhất Tuyết: Ngày 27 tháng 8. À! Là ngày sinh nhật của em!\nLưu Minh: Chúc mừng sinh nhật! Mặc dù em quên, nhưng anh vẫn nhớ. Em nhìn xem, đây là cái gì nào?\nVương Nhất Tuyết: Đồng hồ đeo tay! Ăn cơm, xem phim, rồi còn mua đồng hồ nữa. Hôm nay anh đã tiêu tốn không ít tiền nhỉ?\nLưu Minh: Mặc dù đã tiêu một ít tiền, nhưng chúng ta đã đón một sinh nhật vui vẻ.", "audio_dialogue": "8-5 @xitoytili_luoluodafang.mp3", "audio_vocab": "8-6 @xitoytili_luoluodafang.mp3"}, {"label": "Bài khóa 4", "type": "passage", "lines": [{"speaker": "", "cn": "虽然妻子忘了今天是自己的生日，但是丈夫记得。丈夫请妻子去饭馆吃饭，去电影院看电影，还给妻子买了一块非常漂亮的手表。妻子觉得今天很快乐。", "pinyin": "Suīrán qīzi wàngle jīntiān shì zìjǐ de shēngrì, dànshì zhàngfū jìde. Zhàngfū qǐng qīzi qù fànguǎn chī fàn, qù diànyǐngyuàn kàn diànyǐng, hái gěi qīzi mǎile yí kuài fēicháng piàoliang de shǒubiǎo. Qīzi juéde jīntiān hěn kuàilè."}], "translation_vn": "Mặc dù người vợ quên mất hôm nay là sinh nhật của mình, nhưng người chồng vẫn nhớ. Anh ấy mời vợ đi ăn ở nhà hàng, đi xem phim ở rạp chiếu phim, còn mua cho cô ấy một chiếc đồng hồ rất đẹp. Vợ cảm thấy hôm nay rất vui vẻ.", "audio_dialogue": "8-7 @xitoytili_luoluodafang.mp3", "audio_vocab": "8-8 @xitoytili_luoluodafang.mp3"}]}, {"id": 9, "title_cn": "我去买杯奶茶", "title_pinyin": "Wǒ qù mǎi bēi nǎichá", "title_vn": "Em đi mua một cốc trà sữa", "goals": ["能听懂并使用\"没有\"描述事物之间的差别。Có thể nghe hiểu và sử dụng được \"没有\" để miêu tả sự khác biệt giữa các sự vật.", "掌握动词\"离\"的用法，能表达处所或时间的距离。Nắm vững cách dùng của động từ \"离\" để diễn đạt khoảng cách không gian hoặc thời gian.", "掌握时量补语(1)的用法，能描述动作持续的时间。Nắm vững cách dùng của bổ ngữ thời lượng (1) để miêu tả một hành động kéo dài trong bao lâu."], "vocab": [{"hanzi": "坏", "pinyin": "huài", "pos": "tt.", "vn": "xấu, hỏng"}, {"hanzi": "旁边", "pinyin": "pángbiān", "pos": "dt.", "vn": "bên cạnh"}, {"hanzi": "男孩儿", "pinyin": "nánháir", "pos": "dt.", "vn": "con trai, cậu bé"}, {"hanzi": "这样", "pinyin": "zhèyàng", "pos": "dt.", "vn": "như thế này"}, {"hanzi": "个子", "pinyin": "gèzi", "pos": "dt.", "vn": "chiều cao"}, {"hanzi": "那么", "pinyin": "nàme", "pos": "dt.", "vn": "như thế, vậy"}, {"hanzi": "高", "pinyin": "gāo", "pos": "tt.", "vn": "cao"}, {"hanzi": "门口", "pinyin": "ménkǒu", "pos": "dt.", "vn": "cửa ra vào, cổng"}, {"hanzi": "咖啡", "pinyin": "kāfēi", "pos": "dt.", "vn": "cà phê"}, {"hanzi": "离", "pinyin": "lí", "pos": "dgt.", "vn": "cách, cách xa"}, {"hanzi": "近", "pinyin": "jìn", "pos": "tt.", "vn": "gần"}, {"hanzi": "走路", "pinyin": "zǒulù", "pos": "dgt.", "vn": "đi bộ"}, {"hanzi": "周", "pinyin": "zhōu", "pos": "dt.", "vn": "tuần"}], "grammar": [{"title": "比较句 (3) (Câu so sánh (3))", "explanation_vn": "Bài này học cách dùng \"没有\" để biểu thị câu so sánh, mang ý nghĩa \"không bằng\", \"không kịp\". Cấu trúc cơ bản: A没有B + tính từ/cụm tính từ. Trước tính từ có thể thêm \"这么\" hoặc \"那么\" để chỉ mức độ cao hơn của B. Hình thức khẳng định của \"没有\" là \"有\", thường được dùng trong câu nghi vấn so sánh.", "examples": [{"cn": "儿子的个子没有他那么高。", "pinyin": "Érzi de gèzi méiyǒu tā nàme gāo.", "vn": ""}, {"cn": "昨天没有今天这么冷。", "pinyin": "Zuótiān méiyǒu jīntiān zhème lěng.", "vn": ""}, {"cn": "这块手表没有那块好看。", "pinyin": "Zhè kuài shǒubiǎo méiyǒu nà kuài hǎokàn.", "vn": ""}, {"cn": "妹妹有姐姐高吗？", "pinyin": "Mèimei yǒu jiějie gāo ma?", "vn": ""}, {"cn": "那件衣服有这件好看吗？", "pinyin": "Nà jiàn yīfu yǒu zhè jiàn hǎokàn ma?", "vn": ""}]}, {"title": "动词 \"离\" (Động từ \"离\")", "explanation_vn": "Động từ \"离\" được dùng để biểu thị khoảng cách về không gian hoặc thời gian. Cấu trúc cơ bản: A 离 B……", "examples": [{"cn": "咖啡店离这儿有点儿远。", "pinyin": "Kāfēidiàn lí zhèr yǒudiǎnr yuǎn.", "vn": ""}, {"cn": "学校离医院不远。", "pinyin": "Xuéxiào lí yīyuàn bù yuǎn.", "vn": ""}, {"cn": "现在离我的生日还有三天。", "pinyin": "Xiànzài lí wǒ de shēngrì hái yǒu sān tiān.", "vn": ""}]}, {"title": "时量补语 (1) (Bổ ngữ thời lượng (1))", "explanation_vn": "Từ ngữ biểu thị khoảng thời gian được đặt sau động từ làm bổ ngữ thời lượng để miêu tả thời gian mà hành động hoặc trạng thái diễn ra. Cấu trúc cơ bản: Chủ ngữ + động từ + bổ ngữ thời lượng. Khi sau động từ có tân ngữ, vị trí tân ngữ có hai trường hợp: nếu là danh từ chỉ sự vật, thường đặt sau bổ ngữ thời lượng; nếu là từ xưng hô hoặc đại từ, thường đặt trước bổ ngữ thời lượng. Khi động từ có tân ngữ cũng có thể lặp lại động từ rồi mới thêm bổ ngữ thời lượng; nếu động từ là từ li hợp, cần lặp lại từ tố mang tính động từ trước khi thêm bổ ngữ thời lượng. Khi sau động từ có \"了\" và cuối câu cũng có trợ từ ngữ khí \"了\", điều đó biểu thị hành động vẫn đang tiếp diễn.", "examples": [{"cn": "我看了一个晚上电视。", "pinyin": "Wǒ kànle yí gè wǎnshang diànshì.", "vn": ""}, {"cn": "他们学了两年。", "pinyin": "Tāmen xuéle liǎng nián.", "vn": ""}, {"cn": "我找了陈天中二十多分钟。", "pinyin": "Wǒ zhǎole Chén Tiānzhōng èrshí duō fēnzhōng.", "vn": ""}, {"cn": "他们学中文学了两年。", "pinyin": "Tāmen xué Zhōngwén xuéle liǎng nián.", "vn": ""}, {"cn": "安妮游泳游了一个下午。", "pinyin": "Ānnī yóuyǒng yóule yí gè xiàwǔ.", "vn": ""}, {"cn": "他写了半个小时汉字了。（他现在还在写汉字。）", "pinyin": "Tā xiěle bàn gè xiǎoshí Hànzì le. (Tā xiànzài hái zài xiě Hànzì.)", "vn": ""}, {"cn": "陈天中跑步跑了两个小时了。（陈天中还在跑步。）", "pinyin": "Chén Tiānzhōng pǎobù pǎole liǎng gè xiǎoshí le. (Chén Tiānzhōng hái zài pǎobù.)", "vn": ""}]}], "texts": [{"label": "Bài khóa 1", "type": "dialogue", "lines": [{"speaker": "Wáng Yīxuě (王一雪)", "cn": "儿子的裤子坏了，我们给他买条新的吧。", "pinyin": "Érzi de kùzi huài le, wǒmen gěi tā mǎi tiáo xīn de ba."}, {"speaker": "Liú Míng (刘明)", "cn": "好啊。", "pinyin": "Hǎo a."}, {"speaker": "Wáng Yīxuě (王一雪)", "cn": "你看这条黑色的怎么样？", "pinyin": "Nǐ kàn zhè tiáo hēisè de zěnmeyàng?"}, {"speaker": "Liú Míng (刘明)", "cn": "没有你上次买的那条好看。", "pinyin": "Méiyǒu nǐ shàng cì mǎi de nà tiáo hǎokàn."}, {"speaker": "Wáng Yīxuě (王一雪)", "cn": "旁边那个男孩儿就穿了这样的裤子，我觉得很好看啊！", "pinyin": "Pángbiān nàge nánháir jiù chuānle zhèyàng de kùzi, wǒ juéde hěn hǎokàn a!"}, {"speaker": "Liú Míng (刘明)", "cn": "儿子的个子没有他那么高，穿上就不会太好看。", "pinyin": "Érzi de gèzi méiyǒu tā nàme gāo, chuānshang jiù bú huì tài hǎokàn."}, {"speaker": "Wáng Yīxuě (王一雪)", "cn": "好吧，我们再去那边看看。", "pinyin": "Hǎo ba, wǒmen zài qù nàbian kànkan."}], "translation_vn": "Vương Nhất Tuyết: Quần của con trai bị rách rồi, chúng ta mua cho con một chiếc mới đi.\nLưu Minh: Nhất trí nhé.\nVương Nhất Tuyết: Anh xem chiếc màu đen này thế nào?\nLưu Minh: Không đẹp bằng chiếc mà em đã mua lần trước.\nVương Nhất Tuyết: Cậu bé bên cạnh đang mặc kiểu quần này đấy, em thấy rất đẹp mà!\nLưu Minh: Con trai chúng ta không cao bằng cậu bé đó, mặc vào có thể không đẹp được đâu.\nVương Nhất Tuyết: Vâng, chúng ta qua bên kia xem thêm nhé.", "audio_dialogue": "9-1 @xitoytili_luoluodafang.mp3", "audio_vocab": "9-2 @xitoytili_luoluodafang.mp3"}, {"label": "Bài khóa 2", "type": "dialogue", "lines": [{"speaker": "Wáng Yīxuě (王一雪)", "cn": "门口有家奶茶店。你想喝杯奶茶吗？", "pinyin": "Ménkǒu yǒu jiā nǎichádiàn. Nǐ xiǎng hē bēi nǎichá ma?"}, {"speaker": "Liú Míng (刘明)", "cn": "我想喝咖啡，还是去咖啡店吧。", "pinyin": "Wǒ xiǎng hē kāfēi, háishi qù kāfēidiàn ba."}, {"speaker": "Wáng Yīxuě (王一雪)", "cn": "咖啡店离这儿有点儿远。", "pinyin": "Kāfēidiàn lí zhèr yǒudiǎnr yuǎn."}, {"speaker": "Liú Míng (刘明)", "cn": "没关系，那家店的咖啡很好喝。", "pinyin": "Méi guānxi, nà jiā diàn de kāfēi hěn hǎohē."}, {"speaker": "Wáng Yīxuě (王一雪)", "cn": "那你等一下，我去买杯奶茶。", "pinyin": "Nà nǐ děng yíxià, wǒ qù mǎi bēi nǎichá."}, {"speaker": "Liú Míng (刘明)", "cn": "你不想喝咖啡吗？", "pinyin": "Nǐ bù xiǎng hē kāfēi ma?"}, {"speaker": "Wáng Yīxuě (王一雪)", "cn": "喝了咖啡，晚上就别想睡觉了。", "pinyin": "Hēle kāfēi, wǎnshang jiù bié xiǎng shuìjiào le."}], "translation_vn": "Vương Nhất Tuyết: Trước cửa có quán trà sữa. Anh có muốn uống trà sữa không?\nLưu Minh: Anh muốn uống cà phê, hay đến quán cà phê đi.\nVương Nhất Tuyết: Quán cà phê cách chỗ này hơi xa.\nLưu Minh: Không sao đâu, cà phê ở quán đó rất ngon.\nVương Nhất Tuyết: Vậy anh đợi một lát, em đi mua một cốc trà sữa.\nLưu Minh: Em không muốn uống cà phê sao?\nVương Nhất Tuyết: Uống cà phê thì buổi tối khó ngủ mất.", "audio_dialogue": "9-3 @xitoytili_luoluodafang.mp3", "audio_vocab": "9-4 @xitoytili_luoluodafang.mp3"}, {"label": "Bài khóa 3", "type": "dialogue", "lines": [{"speaker": "Liú Míng (刘明)", "cn": "我们打车回去吧。", "pinyin": "Wǒmen dǎchē huíqù ba."}, {"speaker": "Wáng Yīxuě (王一雪)", "cn": "这里离家很近，还是走路吧。", "pinyin": "Zhèlǐ lí jiā hěn jìn, háishi zǒulù ba."}, {"speaker": "Liú Míng (刘明)", "cn": "要走多长时间？", "pinyin": "Yào zǒu duō cháng shíjiān?"}, {"speaker": "Wáng Yīxuě (王一雪)", "cn": "走半个多小时就到了。", "pinyin": "Zǒu bàn gè duō xiǎoshí jiù dào le."}, {"speaker": "Liú Míng (刘明)", "cn": "好的。每天上下班都坐车，今天运动运动吧。", "pinyin": "Hǎo de. Měitiān shàngxià bān dōu zuò chē, jīntiān yùndòng yùndòng ba."}], "translation_vn": "Lưu Minh: Chúng ta bắt taxi về nhé.\nVương Nhất Tuyết: Chỗ này cách nhà mình rất gần, hay là đi bộ về đi.\nLưu Minh: Đi bộ mất bao lâu vậy?\nVương Nhất Tuyết: Đi bộ hơn nửa tiếng thì sẽ tới.\nLưu Minh: Được rồi. Hàng ngày anh đi làm bằng ô tô, hôm nay vận động một chút vậy.", "audio_dialogue": "9-5 @xitoytili_luoluodafang.mp3", "audio_vocab": "9-6 @xitoytili_luoluodafang.mp3"}, {"label": "Bài khóa 4", "type": "passage", "lines": [{"speaker": "", "cn": "这周刘明休息，我下班后跟他去了一家商店。商店里边的衣服没有大商场里的好看。我们没有买到喜欢的衣服，从商店出来就到咖啡店坐了坐。因为想运动运动，所以喝完东西，我们就走回家了。", "pinyin": "Zhè zhōu Liú Míng xiūxi, wǒ xiàbān hòu gēn tā qùle yì jiā shāngdiàn. Shāngdiàn lǐbian de yīfu méiyǒu dà shāngchǎng lǐ de hǎokàn. Wǒmen méiyǒu mǎidào xǐhuan de yīfu, cóng shāngdiàn chūlái jiù dào kāfēidiàn zuòle zuò. Yīnwèi xiǎng yùndòng yùndòng, suǒyǐ hēwán dōngxi, wǒmen jiù zǒuhuí jiā le."}], "translation_vn": "Tuần này, Lưu Minh được nghỉ, sau giờ làm tôi đã đi cùng anh ấy đến một cửa hàng. Quần áo trong cửa hàng đó không đẹp bằng quần áo trong trung tâm thương mại. Chúng tôi không mua được quần áo nào mình thích, vì vậy sau khi rời cửa hàng, chúng tôi đến quán cà phê ngồi một lúc. Vì muốn vận động một chút, nên sau khi uống xong cà phê chúng tôi đã đi bộ về nhà.", "audio_dialogue": "9-7 @xitoytili_luoluodafang.mp3", "audio_vocab": "9-8 @xitoytili_luoluodafang.mp3"}]}, {"id": 10, "title_cn": "就要考试了", "title_pinyin": "Jiù yào kǎoshì le", "title_vn": "Sắp thi rồi", "goals": ["能听懂并使用主谓谓语句对人、事物或情况进行说明。Có thể nghe hiểu và sử dụng được câu có cụm chủ vị làm vị ngữ để miêu tả người, sự vật hoặc tình huống.", "能听懂并使用选择问句表示疑问。Có thể nghe hiểu và sử dụng được câu hỏi lựa chọn để biểu thị nghi vấn.", "掌握固定格式“要/快/快要/就要……了”的用法,能表达某事即将发生。Nắm vững cách dùng của cấu trúc cố định “要/快/快要/就要……了” để diễn đạt một việc nào đó sắp xảy ra."], "vocab": [{"hanzi": "开学", "pinyin": "kāixué", "pos": "dgt.", "vn": "khai giảng"}, {"hanzi": "门", "pinyin": "mén", "pos": "dt.", "vn": "cửa"}, {"hanzi": "后面", "pinyin": "hòumiàn", "pos": "dt.", "vn": "phía sau, đằng sau"}, {"hanzi": "笔", "pinyin": "bǐ", "pos": "dt.", "vn": "bút, viết"}, {"hanzi": "帮", "pinyin": "bāng", "pos": "dgt.", "vn": "giúp, giúp đỡ"}, {"hanzi": "考试", "pinyin": "kǎoshì", "pos": "dgt./dt.", "vn": "thi, kiểm tra, kỳ thi"}, {"hanzi": "词", "pinyin": "cí", "pos": "dt.", "vn": "từ"}, {"hanzi": "本子", "pinyin": "běnzi", "pos": "dt.", "vn": "vở, tập ghi chép"}, {"hanzi": "错", "pinyin": "cuò", "pos": "tt.", "vn": "sai, nhầm"}, {"hanzi": "题", "pinyin": "tí", "pos": "dt.", "vn": "câu hỏi, bài tập, đề, tiêu đề"}, {"hanzi": "还是", "pinyin": "háishi", "pos": "lh.", "vn": "hay là (trong câu hỏi lựa chọn)"}, {"hanzi": "考", "pinyin": "kǎo", "pos": "dgt.", "vn": "thi, kiểm tra"}, {"hanzi": "快要", "pinyin": "kuàiyào", "pos": "phó.", "vn": "sắp, chuẩn bị"}, {"hanzi": "笑", "pinyin": "xiào", "pos": "dgt.", "vn": "cười"}], "grammar": [{"title": "主谓谓语句 Câu có cụm chủ vị làm vị ngữ", "explanation_vn": "主谓短语可以作谓语,对主语加以说明或描写,构成主谓谓语句。一般来说,主谓短语中的主语是全句主语的一部分或跟它相关。基本结构:主语+主谓短语。 Cụm chủ vị có thể làm vị ngữ để giải thích hoặc miêu tả chủ ngữ, từ đó tạo thành câu có cụm chủ vị làm vị ngữ. Thông thường, chủ ngữ trong cụm chủ vị hoặc là một phần của chủ ngữ của cả câu, hoặc có liên quan đến nó. Cấu trúc cơ bản: Chủ ngữ + cụm chủ vị.", "examples": [{"cn": "我的书包你看见了吗?", "pinyin": "", "vn": ""}, {"cn": "弟弟手很小。", "pinyin": "", "vn": ""}, {"cn": "这件事他知道。", "pinyin": "", "vn": ""}]}, {"title": "选择问句 Câu hỏi lựa chọn", "explanation_vn": "连词“还是”用在疑问句中,表示选择。基本结构:(是)A还是B。 Liên từ “还是” dùng trong câu nghi vấn, chỉ sự lựa chọn. Cấu trúc cơ bản: (是)A还是B.", "examples": [{"cn": "妈妈,是您准备考试还是我准备考试?", "pinyin": "", "vn": ""}, {"cn": "你更喜欢打篮球,踢足球还是游泳?", "pinyin": "", "vn": ""}, {"cn": "我们什么时候去看电影?今天还是明天?", "pinyin": "", "vn": ""}]}, {"title": "固定格式“要/快/快要/就要……了”", "explanation_vn": "固定格式“要/快/快要/就要……了”表示某事将要发生。如果句子中有时间语,一般用“就要……了”。 Cấu trúc cố định “要/快/快要/就要……了” dùng để biểu thị một việc sắp xảy ra. Nếu trong câu có thêm trạng ngữ chỉ thời gian thì hay dùng “就要……了”.", "examples": [{"cn": "饭菜快要做好了。", "pinyin": "", "vn": ""}, {"cn": "火车快开了。", "pinyin": "", "vn": ""}, {"cn": "我们下星期就要考试了。", "pinyin": "", "vn": ""}]}], "texts": [{"label": "Bài khóa 1", "type": "dialogue", "lines": [{"speaker": "刘明 (Lưu Minh)", "cn": "小明,你们明天开学,你准备好了吗?", "pinyin": "Xiǎomíng, nǐmen míngtiān kāixué, nǐ zhǔnbèi hǎo le ma?"}, {"speaker": "刘小明 (Lưu Tiểu Minh)", "cn": "明天就开学吗?爸爸,我的书包你看见了吗?", "pinyin": "Míngtiān jiù kāixué ma? Bàba, wǒ de shūbāo nǐ kànjiàn le ma?"}, {"speaker": "刘明 (Lưu Minh)", "cn": "书包在门后面。", "pinyin": "Shūbāo zài mén hòumiàn."}, {"speaker": "刘小明 (Lưu Tiểu Minh)", "cn": "书在哪儿呢?笔呢?", "pinyin": "Shū zài nǎr ne? Bǐ ne?"}, {"speaker": "刘明 (Lưu Minh)", "cn": "书在床上,笔在桌子上。", "pinyin": "Shū zài chuáng shang, bǐ zài zhuōzi shang."}, {"speaker": "刘小明 (Lưu Tiểu Minh)", "cn": "太好了!现在都准备好了。", "pinyin": "Tài hǎo le! Xiànzài dōu zhǔnbèi hǎo le."}, {"speaker": "刘明 (Lưu Minh)", "cn": "这次爸爸帮你,下次你自己准备,好不好?", "pinyin": "Zhè cì bàba bāng nǐ, xià cì nǐ zìjǐ zhǔnbèi, hǎo bu hǎo?"}, {"speaker": "刘小明 (Lưu Tiểu Minh)", "cn": "好!", "pinyin": "Hǎo!"}], "translation_vn": "Lưu Minh: Tiểu Minh, ngày mai khai giảng rồi, con đã chuẩn bị xong chưa? Lưu Tiểu Minh: Ngày mai khai giảng à? Bố ơi, bố có thấy cặp sách của con không? Lưu Minh: Nó ở phía sau cửa. Lưu Tiểu Minh: Sách ở đâu ạ? Cả bút nữa? Lưu Minh: Sách ở trên giường, bút ở trên bàn. Lưu Tiểu Minh: May quá! Bây giờ đã chuẩn bị xong rồi. Lưu Minh: Lần này, bố đã giúp con. Lần sau con phải tự chuẩn bị, được không? Lưu Tiểu Minh: Vâng ạ!", "audio_dialogue": "10-1 @xitoytili_luoluodafang.mp3", "audio_vocab": "10-2 @xitoytili_luoluodafang.mp3"}, {"label": "Bài khóa 2", "type": "dialogue", "lines": [{"speaker": "王一雪 (Vương Nhất Tuyết)", "cn": "小雪,你在做什么呢?", "pinyin": "Xiǎoxuě, nǐ zài zuò shénme ne?"}, {"speaker": "刘小雪 (Lưu Tiểu Tuyết)", "cn": "明天考试,我在看书呢。", "pinyin": "Míngtiān kǎoshì, wǒ zài kàn shū ne."}, {"speaker": "王一雪 (Vương Nhất Tuyết)", "cn": "这些词要好好看看。", "pinyin": "Zhèxiē cí yào hǎohāo kànkan."}, {"speaker": "刘小雪 (Lưu Tiểu Tuyết)", "cn": "我看过了,意思也都懂了。", "pinyin": "Wǒ kànguò le, yìsi yě dōu dǒng le."}, {"speaker": "王一雪 (Vương Nhất Tuyết)", "cn": "你的本子呢?本子上做错的题也要再看看。", "pinyin": "Nǐ de běnzi ne? Běnzi shang zuòcuò de tí yě yào zài kànkan."}, {"speaker": "刘小雪 (Lưu Tiểu Tuyết)", "cn": "妈妈,是您准备考试还是我准备考试呀?", "pinyin": "Māma, shì nín zhǔnbèi kǎoshì háishi wǒ zhǔnbèi kǎoshì ya?"}], "translation_vn": "Vương Nhất Tuyết: Tiểu Tuyết, con đang làm gì vậy? Lưu Tiểu Tuyết: Ngày mai con thi, nên con đang học bài. Vương Nhất Tuyết: Con nên xem lại những từ này thật kỹ nhé. Lưu Tiểu Tuyết: Con xem rồi, cũng đã hiểu hết nghĩa của chúng rồi. Vương Nhất Tuyết: Thế còn vở của con đâu? Những câu làm sai trong vở cũng cần xem lại. Lưu Tiểu Tuyết: Mẹ ơi, là mẹ chuẩn bị thi hay là con chuẩn bị thi vậy?", "audio_dialogue": "10-3 @xitoytili_luoluodafang.mp3", "audio_vocab": "10-4 @xitoytili_luoluodafang.mp3"}, {"label": "Bài khóa 3", "type": "dialogue", "lines": [{"speaker": "刘小雪 (Lưu Tiểu Tuyết)", "cn": "妈妈,我回来了!", "pinyin": "Māma, wǒ huílai le!"}, {"speaker": "王一雪 (Vương Nhất Tuyết)", "cn": "我买了奶茶,就在桌子上,自己去拿吧。", "pinyin": "Wǒ mǎile nǎichá, jiù zài zhuōzi shang, zìjǐ qù ná ba."}, {"speaker": "刘小雪 (Lưu Tiểu Tuyết)", "cn": "谢谢妈妈!", "pinyin": "Xièxie māma!"}, {"speaker": "王一雪 (Vương Nhất Tuyết)", "cn": "今天考试考得怎么样?", "pinyin": "Jīntiān kǎoshì kǎo de zěnmeyàng?"}, {"speaker": "刘小雪 (Lưu Tiểu Tuyết)", "cn": "我觉得比上次好。", "pinyin": "Wǒ juéde bǐ shàng cì hǎo."}, {"speaker": "王一雪 (Vương Nhất Tuyết)", "cn": "真不错!饭菜快要做好了,你叫弟弟一起去洗手吧。", "pinyin": "Zhēn búcuò! Fàncài kuàiyào zuòhǎo le, nǐ jiào dìdi yìqǐ qù xǐshǒu ba."}, {"speaker": "刘小明 (Lưu Tiểu Minh)", "cn": "妈妈,我是第一名,姐姐还没洗完呢。", "pinyin": "Māma, wǒ shì dì-yī míng, jiějie hái méi xǐwán ne."}, {"speaker": "王一雪 (Vương Nhất Tuyết)", "cn": "你洗得真快啊!", "pinyin": "Nǐ xǐ de zhēn kuài a!"}], "translation_vn": "Lưu Tiểu Tuyết: Mẹ ơi, con về rồi! Vương Nhất Tuyết: Mẹ đã mua trà sữa, để ngay trên bàn, con tự đi lấy nhé. Lưu Tiểu Tuyết: Cảm ơn mẹ! Vương Nhất Tuyết: Hôm nay con thi thế nào? Lưu Tiểu Tuyết: Con thấy tốt hơn lần trước. Vương Nhất Tuyết: Thật tuyệt! Cơm sắp nấu xong rồi, con gọi em trai cùng đi rửa tay nhé. Lưu Tiểu Minh: Mẹ ơi, con xong nhanh nhất, chị vẫn chưa rửa tay xong. Vương Nhất Tuyết: Con rửa tay nhanh thật đấy!", "audio_dialogue": "10-5 @xitoytili_luoluodafang.mp3", "audio_vocab": "10-6 @xitoytili_luoluodafang.mp3"}, {"label": "Bài khóa 4", "type": "passage", "lines": [{"speaker": "", "cn": "快要开学了,爸爸帮弟弟准备书包、本子和笔。我就要考试了,妈妈让我看书、看做错的题。我们上学,爸爸、妈妈比我们还忙。我问他们:“是我和弟弟上学还是你们上学?”我问完,他们都笑了。", "pinyin": "Kuàiyào kāixué le, bàba bāng dìdi zhǔnbèi shūbāo, běnzi hé bǐ. Wǒ jiù yào kǎoshì le, māma ràng wǒ kàn shū, kàn zuòcuò de tí. Wǒmen shàngxué, bàba, māma bǐ wǒmen hái máng. Wǒ wèn tāmen: “Shì wǒ hé dìdi shàngxué háishi nǐmen shàngxué?” Wǒ wènwán, tāmen dōu xiào le."}], "translation_vn": "Sắp khai giảng rồi, bố giúp em trai chuẩn bị cặp sách, vở và bút. Tôi sắp thi, mẹ bảo tôi học bài và xem lại những câu làm sai. Chúng tôi đi học, nhưng bố mẹ còn bận hơn cả chúng tôi. Tôi hỏi bố mẹ rằng: “Là em trai và con đi học hay là bố mẹ đi học vậy?” Tôi hỏi xong, cả nhà đều bật cười.", "audio_dialogue": "10-7 @xitoytili_luoluodafang.mp3", "audio_vocab": "10-8 @xitoytili_luoluodafang.mp3"}]}, {"id": 11, "title_cn": "我最喜欢吃中国菜", "title_pinyin": "Wǒ zuì xǐhuan chī Zhōngguó cài", "title_vn": "Em thích ăn món Trung Quốc nhất", "goals": ["能听懂并描述身体状况和病情。Có thể nghe hiểu và miêu tả được tình trạng sức khoẻ.", "能听懂并使用动态助词“着”表达动作或状态的持续。Có thể nghe hiểu và sử dụng được trợ từ động thái “着” để diễn đạt sự duy trì của động tác hoặc trạng thái.", "掌握程度副词“最”的用法,能表达某种属性超过所有同类的人或事物。Nắm vững cách dùng của phó từ chỉ mức độ “最” để diễn đạt một thuộc tính nào đó vượt trội hơn tất cả mọi người hoặc sự vật cùng loại."], "vocab": [{"hanzi": "头", "pinyin": "tóu", "pos": "dt.", "vn": "đầu"}, {"hanzi": "疼", "pinyin": "téng", "pos": "tt.", "vn": "đau, nhức"}, {"hanzi": "经常", "pinyin": "jīngcháng", "pos": "phó.", "vn": "thường xuyên"}, {"hanzi": "动", "pinyin": "dòng", "pos": "đgt.", "vn": "di chuyển, cử động"}, {"hanzi": "着", "pinyin": "zhe", "pos": "trợ.", "vn": "đặt sau động từ hoặc tính từ để chỉ sự duy trì của động tác hoặc trạng thái"}, {"hanzi": "路上", "pinyin": "lùshang", "pos": "dt.", "vn": "trên đường"}, {"hanzi": "慢", "pinyin": "màn", "pos": "tt.", "vn": "chậm"}, {"hanzi": "进", "pinyin": "jìn", "pos": "đgt.", "vn": "vào"}, {"hanzi": "药", "pinyin": "yào", "pos": "dt.", "vn": "thuốc"}, {"hanzi": "身体", "pinyin": "shēntǐ", "pos": "dt.", "vn": "cơ thể, sức khoẻ"}, {"hanzi": "时", "pinyin": "shí", "pos": "dt.", "vn": "khi, lúc"}, {"hanzi": "最", "pinyin": "zuì", "pos": "phó.", "vn": "nhất"}, {"hanzi": "药店", "pinyin": "yàodiàn", "pos": "dt.", "vn": "hiệu thuốc, nhà thuốc"}], "grammar": [{"title": "动态助词“着”(1) Trợ từ động thái “着” (1)", "explanation_vn": "动态助词“着”用在动词后面,表示动作或状态的持续。否定形式是在动词前面加“没(有)”。 Trợ từ động thái “着” đặt sau động từ, biểu thị sự duy trì của động tác hoặc trạng thái. Hình thức phủ định là thêm “没(有)” vào trước động từ.", "examples": [{"cn": "那你在这儿坐着。", "pinyin": "", "vn": ""}, {"cn": "教室的门开着。", "pinyin": "", "vn": ""}, {"cn": "教室的门没开着。", "pinyin": "", "vn": ""}]}, {"title": "动态助词“着”(2) Trợ từ động thái “着” (2)", "explanation_vn": "表示动作或状态持续的句子中,宾语要在动态助词“着”的后面。疑问形式有三种:(1)在句尾加“吗”;(2)在句尾加“没有”;(3)动词+没+动词+着。 Trong câu biểu thị sự duy trì của động tác hoặc trạng thái, tân ngữ phải đứng sau trợ từ động thái “着”. Hình thức nghi vấn có ba loại: (1) thêm “吗” vào cuối câu; (2) thêm “没有” vào cuối câu; (3) động từ + 没 + động từ + 着.", "examples": [{"cn": "现在路上车多,还下着雪,我开慢一点儿。", "pinyin": "", "vn": ""}, {"cn": "她穿着白色的裤子。", "pinyin": "", "vn": ""}, {"cn": "陈天中没拿着咖啡。", "pinyin": "", "vn": ""}, {"cn": "教室的门开着吗?", "pinyin": "", "vn": ""}, {"cn": "白家月坐着没有?", "pinyin": "", "vn": ""}, {"cn": "她拿没拿着手机?", "pinyin": "", "vn": ""}]}, {"title": "程度副词“最” Phó từ chỉ mức độ “最”", "explanation_vn": "程度副词“最”用在形容词或心理动词前面,表示某种属性超过所有同类的人或事物。 Phó từ chỉ mức độ “最” đặt trước tính từ hoặc động từ chỉ tâm lý, biểu thị một đặc tính nào đó vượt trội hơn tất cả mọi người hoặc sự vật cùng loại.", "examples": [{"cn": "你最喜欢吃中国菜。", "pinyin": "", "vn": ""}, {"cn": "在我们家,爸爸最高。", "pinyin": "", "vn": ""}, {"cn": "你们班谁说中文说得最好?", "pinyin": "", "vn": ""}]}], "texts": [{"label": "Bài khóa 1", "type": "dialogue", "lines": [{"speaker": "王一飞 (Vương Nhất Phi)", "cn": "家月,都下课了,你怎么还不回家?", "pinyin": "Jiāyuè, dōu xiàkè le, nǐ zěnme hái bù huí jiā?"}, {"speaker": "白家月 (Bạch Gia Nguyệt)", "cn": "我头疼,不太舒服。", "pinyin": "Wǒ tóu téng, bú tài shūfu."}, {"speaker": "王一飞 (Vương Nhất Phi)", "cn": "你这几天经常头疼,去医院看看吧。", "pinyin": "Nǐ zhè jǐ tiān jīngcháng tóu téng, qù yīyuàn kànkan ba."}, {"speaker": "白家月 (Bạch Gia Nguyệt)", "cn": "我想休息一下,现在不能动,一动就疼。", "pinyin": "Wǒ xiǎng xiūxi yíxià, xiànzài bù néng dòng, yí dòng jiù téng."}, {"speaker": "王一飞 (Vương Nhất Phi)", "cn": "那你在这儿坐着,我去开车,一会儿送你去医院。", "pinyin": "Nà nǐ zài zhèr zuòzhe, wǒ qù kāichē, yìhuǐr sòng nǐ qù yīyuàn."}, {"speaker": "白家月 (Bạch Gia Nguyệt)", "cn": "谢谢王老师。", "pinyin": "Xièxie Wáng lǎoshī."}], "translation_vn": "Vương Nhất Phi: Gia Nguyệt, đã tan học rồi, sao em vẫn chưa về nhà? Bạch Gia Nguyệt: Em bị đau đầu, không được khỏe lắm. Vương Nhất Phi: Mấy ngày nay em thường xuyên đau đầu, hay là đi bệnh viện khám thử xem. Bạch Gia Nguyệt: Em muốn nghỉ ngơi một lát, bây giờ không cử động được, cứ di cử là đau. Vương Nhất Phi: Vậy em cứ ngồi ở đây nhé, cô đi lấy xe, lát nữa sẽ đưa em đến bệnh viện. Bạch Gia Nguyệt: Cảm ơn cô Vương ạ.", "audio_dialogue": "11-1 @xitoytili_luoluodafang.mp3", "audio_vocab": "11-2 @xitoytili_luoluodafang.mp3"}, {"label": "Bài khóa 2", "type": "dialogue", "lines": [{"speaker": "王一飞 (Vương Nhất Phi)", "cn": "现在路上车多,还下着雪,我开慢一点儿。", "pinyin": "Xiànzài lùshang chē duō, hái xiàzhe xuě, wǒ kāi màn yìdiǎnr."}, {"speaker": "白家月 (Bạch Gia Nguyệt)", "cn": "没问题,现在头没那么疼了。", "pinyin": "Méi wèntí, xiànzài tóu méi nàme téng le."}, {"speaker": "王一飞 (Vương Nhất Phi)", "cn": "好。李文来电话了,你帮我接一下。", "pinyin": "Hǎo. Lǐ Wén lái diànhuà le, nǐ bāng wǒ jiē yíxià."}, {"speaker": "白家月 (Bạch Gia Nguyệt)", "cn": "喂,李文。王老师开着车呢。你找他有事吗?", "pinyin": "Wéi, Lǐ Wén. Wáng lǎoshī kāizhe chē ne. Nǐ zhǎo tā yǒu shì ma?"}, {"speaker": "李文 (Lý Văn)", "cn": "没什么事。今天雪这么大,你们开车去哪儿啊?", "pinyin": "Méi shénme shì. Jīntiān xuě zhème dà, nǐmen kāichē qù nǎr a?"}, {"speaker": "白家月 (Bạch Gia Nguyệt)", "cn": "去医院。我头有点儿疼。", "pinyin": "Qù yīyuàn. Wǒ tóu yǒudiǎnr téng."}, {"speaker": "李文 (Lý Văn)", "cn": "那我一会儿去看看你。", "pinyin": "Nà wǒ yíhuìr qù kànkan nǐ."}], "translation_vn": "Vương Nhất Phi: Bây giờ rất nhiều xe cộ trên đường, lại còn đang có tuyết rơi nên cô lái chậm một chút. Bạch Gia Nguyệt: Không sao đâu ạ, bây giờ đầu em không còn đau như vừa nãy nữa rồi. Vương Nhất Phi: Được rồi. Lý Văn gọi điện thoại đến kìa, em nghe máy hộ cô một chút. Bạch Gia Nguyệt: A lô, Lý Văn à, cô Vương đang lái xe, bạn tìm cô có việc gì không? Lý Văn: Không có việc gì quan trọng. Hôm nay tuyết rơi dày thế này, hai người có đi đâu vậy? Bạch Gia Nguyệt: Đi bệnh viện, mình hơi đau đầu. Lý Văn: Vậy lát nữa mình sẽ đi thăm bạn.", "audio_dialogue": "11-3 @xitoytili_luoluodafang.mp3", "audio_vocab": "11-4 @xitoytili_luoluodafang.mp3"}, {"label": "Bài khóa 3", "type": "dialogue", "lines": [{"speaker": "白家月 (Bạch Gia Nguyệt)", "cn": "李文,快请进!", "pinyin": "Lǐ Wén, kuài qǐng jìn!"}, {"speaker": "李文 (Lý Văn)", "cn": "家月,你怎么样了?头还疼吗?", "pinyin": "Jiāyuè, nǐ zěnmeyàng le? Tóu hái téng ma?"}, {"speaker": "白家月 (Bạch Gia Nguyệt)", "cn": "不那么疼了。医生开了一些药,吃完就好多了。", "pinyin": "Bú nàme téng le. Yīshēng kāile yìxiē yào, chīwán jiù hǎoduō le."}, {"speaker": "李文 (Lý Văn)", "cn": "那就好!", "pinyin": "Nà jiù hǎo!"}, {"speaker": "王一飞 (Vương Nhất Phi)", "cn": "家月,你想不想吃点儿东西?", "pinyin": "Jiāyuè, nǐ xiǎng bu xiǎng chī diǎnr dōngxi?"}, {"speaker": "李文 (Lý Văn)", "cn": "吃点儿吧,身体不舒服时更要好好吃饭。", "pinyin": "Chī diǎnr ba, shēntǐ bù shūfu shí gèng yào hǎohāo chī fàn."}, {"speaker": "白家月 (Bạch Gia Nguyệt)", "cn": "吃点儿什么呢?", "pinyin": "Chī diǎnr shénme ne?"}, {"speaker": "王一飞 (Vương Nhất Phi)", "cn": "你最喜欢吃中国菜,我做几个中国菜吧。", "pinyin": "Nǐ zuì xǐhuan chī Zhōngguó cài, wǒ zuò jǐ ge Zhōngguó cài ba."}, {"speaker": "白家月 (Bạch Gia Nguyệt)", "cn": "好的,谢谢王老师。", "pinyin": "Hǎo de, xièxie Wáng lǎoshī."}], "translation_vn": "Bạch Gia Nguyệt: Lý Văn, mau vào đi! Lý Văn: Gia Nguyệt, bạn thế nào rồi? Còn đau đầu không? Bạch Gia Nguyệt: Không đau như trước nữa rồi. Bác sĩ đã kê một ít thuốc, uống xong thấy khoẻ hơn nhiều rồi. Lý Văn: Vậy thì tốt rồi! Vương Nhất Phi: Gia Nguyệt, em có muốn ăn chút gì không? Lý Văn: Ăn một chút đi, khi cơ thể không khoẻ thì càng phải ăn uống đầy đủ. Bạch Gia Nguyệt: Ăn chút gì bây giờ? Vương Nhất Phi: Em thích ăn món Trung Quốc nhất, cô sẽ nấu mấy món Trung Quốc nhé. Bạch Gia Nguyệt: Vâng ạ, cám ơn cô Vương.", "audio_dialogue": "11-5 @xitoytili_luoluodafang.mp3", "audio_vocab": "11-6 @xitoytili_luoluodafang.mp3"}, {"label": "Bài khóa 4", "type": "passage", "lines": [{"speaker": "", "cn": "我这几天经常头疼,从药店买了点儿药,没去医院。今天下课后,王老师看我不舒服,就送我去医院。从医院回来,李文也来看我了。现在他们都回去了,我也要睡觉了。", "pinyin": "Wǒ zhè jǐ tiān jīngcháng tóuténg, cóng yàodiàn mǎile diǎnr yào, méi qù yīyuàn. Jīntiān xiàkè hòu, Wáng lǎoshī kàn wǒ bù shūfu, jiù sòng wǒ qù yīyuàn le. Cóng yīyuàn huílai, Lǐ Wén yě lái kàn wǒ le. Xiànzài tāmen dōu huíqù le, wǒ yě yào shuìjiào le."}], "translation_vn": "Mấy ngày nay tôi thường xuyên bị đau đầu, đã mua một ít thuốc từ hiệu thuốc về mà không đi bệnh viện. Hôm nay sau khi tan học, cô Vương thấy tôi không được khoẻ nên đã đưa tôi đến bệnh viện. Sau khi từ bệnh viện về, Lý Văn cũng đến thăm tôi. Bây giờ họ đều về cả rồi, tôi cũng phải đi ngủ đây.", "audio_dialogue": "11-7 @xitoytili_luoluodafang.mp3", "audio_vocab": "11-8 @xitoytili_luoluodafang.mp3"}]}, {"id": 12, "title_cn": "这里比北京冷多了", "title_pinyin": "Zhèlǐ bǐ Běijīng lěng duō le", "title_vn": "Ở đây lạnh hơn Bắc Kinh nhiều", "goals": ["能听懂并谈论天气情况。Có thể nghe hiểu và thảo luận được tình hình thời tiết.", "能听懂并描述动作状态之间的差别。Có thể nghe hiểu và miêu tả được sự khác biệt giữa các trạng thái của động tác.", "掌握比较句的用法,能说明事物之间的差别很大。Nắm vững cách dùng của câu so sánh để nói rõ sự khác biệt lớn giữa các sự vật."], "vocab": [{"hanzi": "事情", "pinyin": "shìqing", "pos": "dt.", "vn": "sự việc, việc"}, {"hanzi": "晴", "pinyin": "qíng", "pos": "tt.", "vn": "nắng, tạnh ráo, quang đãng"}, {"hanzi": "正", "pinyin": "zhèng", "pos": "phó.", "vn": "đang (chỉ hành động hoặc trạng thái đang diễn ra)"}, {"hanzi": "外面", "pinyin": "wàimiàn", "pos": "dt.", "vn": "bên ngoài"}, {"hanzi": "阴", "pinyin": "yīn", "pos": "tt.", "vn": "âm u, có mây, râm"}, {"hanzi": "从小", "pinyin": "cóngxiǎo", "pos": "phó.", "vn": "từ nhỏ"}, {"hanzi": "地铁", "pinyin": "dìtiě", "pos": "dt.", "vn": "tàu điện ngầm"}, {"hanzi": "楼", "pinyin": "lóu", "pos": "dt.", "vn": "toà nhà, lầu, tầng"}, {"hanzi": "站", "pinyin": "zhàn", "pos": "dt.", "vn": "trạm, bến"}, {"hanzi": "小时候", "pinyin": "xiǎoshíhou", "pos": "dt.", "vn": "lúc nhỏ, thời thơ ấu"}, {"hanzi": "好", "pinyin": "hǎo", "pos": "phó.", "vn": "rất, thật là"}], "grammar": [{"title": "比较句(4) Câu so sánh (4)", "explanation_vn": "用“比”表示的比较句中,“多了”或“得多”用在形容词后面,表示差别很大。基本结构:A比B+形容词+多了/得多。 Trong câu so sánh dùng “比”, “多了” hoặc “得多” đặt sau tính từ để biểu thị sự khác biệt rất lớn. Cấu trúc cơ bản: A比B+tính từ+多了/得多.", "examples": [{"cn": "我这里比北京冷多了。", "pinyin": "", "vn": ""}, {"cn": "坐飞机比坐火车快得多。", "pinyin": "", "vn": ""}, {"cn": "他觉得红茶比绿茶好喝得多。", "pinyin": "", "vn": ""}]}, {"title": "比较句(5) Câu so sánh (5)", "explanation_vn": "用“比”表示的比较句中,如果动词带状态补语,“比”用在动词前后都可以。 Trong câu so sánh dùng “比”, nếu động từ có bổ ngữ trạng thái, “比” có thể đặt trước hoặc đặt sau động từ.", "examples": [{"cn": "昨天比今天下得大。", "pinyin": "", "vn": ""}, {"cn": "妈妈比我睡得晚。", "pinyin": "", "vn": ""}, {"cn": "李文跑得比白家月快。", "pinyin": "", "vn": ""}]}, {"title": "比较句(6) Câu so sánh (6)", "explanation_vn": "用“比”表示的比较句中,如果动词既带宾语,又带状态补语,可以把宾语提前,或者重复动词。如果动词是离合词,需要重复动词性语素。 Trong câu so sánh dùng “比”, nếu động từ vừa mang tân ngữ vừa mang bổ ngữ trạng thái thì có thể đưa tân ngữ lên trước hoặc lặp lại động từ. Nếu động từ là từ li hợp thì cần lặp lại từ tố mang tính chất động từ.", "examples": [{"cn": "你跑步跑得比我快。", "pinyin": "", "vn": ""}, {"cn": "白家月汉字写得比陈天好。", "pinyin": "", "vn": ""}, {"cn": "他踢足球比我踢得好。", "pinyin": "", "vn": ""}]}], "texts": [{"label": "Bài khóa 1", "type": "dialogue", "lines": [{"speaker": "王一雪 (Vương Nhất Tuyết)", "cn": "喂,家月,是你啊!有什么事情吗?", "pinyin": "Wéi, Jiāyuè, shì nǐ a! Yǒu shénme shìqing ma?"}, {"speaker": "白家月 (Bạch Gia Nguyệt)", "cn": "没什么事,就想跟您说说话。", "pinyin": "Méi shénme shì, jiù xiǎng gēn nín shuōshuo huà."}, {"speaker": "王一雪 (Vương Nhất Tuyết)", "cn": "好啊。你今天没课吗?", "pinyin": "Hǎo a. Nǐ jīntiān méi kè ma?"}, {"speaker": "白家月 (Bạch Gia Nguyệt)", "cn": "下午有课。您那里天气怎么样?", "pinyin": "Xiàwǔ yǒu kè. Nín nàlǐ tiānqì zěnmeyàng?"}, {"speaker": "王一雪 (Vương Nhất Tuyết)", "cn": "北京这几天虽然是晴天,但是有点儿冷。", "pinyin": "Běijīng zhè jǐ tiān suīrán shì qíngtiān, dànshì yǒudiǎnr lěng."}, {"speaker": "白家月 (Bạch Gia Nguyệt)", "cn": "我这里比北京冷多了,外边还正下着雪呢!", "pinyin": "Wǒ zhèlǐ bǐ Běijīng lěngduō le, wàibian hái zhèng xiàzhe xuě ne!"}], "translation_vn": "Vương Nhất Tuyết: A lô, Gia Nguyệt, là em à! Có việc gì không? Bạch Gia Nguyệt: Không có việc gì ạ, chỉ là muốn trò chuyện với chị một chút thôi. Vương Nhất Tuyết: Được chứ. Hôm nay em không lên lớp à? Bạch Gia Nguyệt: Buổi chiều em mới có tiết. Thời tiết chỗ chị thế nào? Vương Nhất Tuyết: Mấy ngày hôm nay, Bắc Kinh tuy nắng nhưng vẫn hơi lạnh. Bạch Gia Nguyệt: Chỗ em lạnh hơn Bắc Kinh nhiều, bên ngoài tuyết vẫn đang rơi đấy!", "audio_dialogue": "12-1 @xitoytili_luoluodafang.mp3", "audio_vocab": "12-2 @xitoytili_luoluodafang.mp3"}, {"label": "Bài khóa 2", "type": "dialogue", "lines": [{"speaker": "王一雪 (Vương Nhất Tuyết)", "cn": "喂,一飞,听家月说你那边下雪了,下得大不大?", "pinyin": "Wéi, Yīfēi, tīng Jiāyuè shuō nǐ nàbiān xià xuě le, xià de dà bu dà?"}, {"speaker": "王一飞 (Vương Nhất Phi)", "cn": "今天不大,昨天比今天下得大。", "pinyin": "Jīntiān bú dà, zuótiān bǐ jīntiān xià de dà."}, {"speaker": "王一雪 (Vương Nhất Tuyết)", "cn": "天气不好,你去外面的时候多穿点儿衣服。", "pinyin": "Tiānqì bù hǎo, nǐ qù wàimiàn de shíhou duō chuān diǎnr yīfu."}, {"speaker": "王一飞 (Vương Nhất Phi)", "cn": "这几天我在网上上课,没出去过。", "pinyin": "Zhè jǐ tiān wǒ zài wǎngshang shàngkè, méi chūqù guo."}, {"speaker": "王一雪 (Vương Nhất Tuyết)", "cn": "那就好,有事记得给我打电话。", "pinyin": "Nà jiù hǎo, yǒu shì jìde gěi wǒ dǎ diànhuà."}, {"speaker": "王一飞 (Vương Nhất Phi)", "cn": "好的。现在不下雪了,我出去买点儿吃的。", "pinyin": "Hǎo de. Xiànzài bú xià xuě le, wǒ chūqù mǎi diǎnr chī de."}, {"speaker": "王一雪 (Vương Nhất Tuyết)", "cn": "一次多买点儿,阴天下雪什么的就少出去吧。", "pinyin": "Yí cì duō mǎi diǎnr, yīntiān xià xuě shénme de jiù shǎo chūqù ba."}], "translation_vn": "Vương Nhất Tuyết: A lô, Nhất Phi à, nghe Gia Nguyệt nói chỗ em tuyết rơi rồi, tuyết to không em? Vương Nhất Phi: Hôm nay không to, hôm qua tuyết to hơn hôm nay. Vương Nhất Tuyết: Thời tiết xấu, khi đi ra ngoài, em nhớ mặc thêm nhiều quần áo một chút nhé. Vương Nhất Phi: Mấy ngày nay em dạy online nên không đi ra ngoài. Vương Nhất Tuyết: Vậy thì tốt rồi, có việc gì nhớ gọi điện cho chị nhé. Vương Nhất Phi: Vâng ạ. Bây giờ tuyết ngừng rơi rồi, em ra ngoài mua chút đồ ăn. Vương Nhất Tuyết: Mỗi lần mua thì nên mua nhiều một chút, những lúc trời âm u hoặc có tuyết thì nên hạn chế ra ngoài.", "audio_dialogue": "12-3 @xitoytili_luoluodafang.mp3", "audio_vocab": "12-4 @xitoytili_luoluodafang.mp3"}, {"label": "Bài khóa 3", "type": "dialogue", "lines": [{"speaker": "李文 (Lý Văn)", "cn": "喂,家月,今天天气不错,我们去跑步吧!", "pinyin": "Wèi, Jiāyuè, jīntiān tiānqì búcuò, wǒmen qù pǎobù ba!"}, {"speaker": "白家月 (Bạch Gia Nguyệt)", "cn": "你跑步跑得比我快,我们能一起跑吗?", "pinyin": "Nǐ pǎobù pǎo de bǐ wǒ kuài, wǒmen néng yìqǐ pǎo ma?"}, {"speaker": "李文 (Lý Văn)", "cn": "可以的,我慢慢跑,等着你。", "pinyin": "Kěyǐ de, wǒ mànmàn pǎo, děngzhe nǐ."}, {"speaker": "白家月 (Bạch Gia Nguyệt)", "cn": "好吧。你真爱跑步啊!", "pinyin": "Hǎo ba. Nǐ zhēn ài pǎobù a!"}, {"speaker": "李文 (Lý Văn)", "cn": "我从小就经常跟爸爸跑步,跑步能让人快乐。", "pinyin": "Wǒ cóngxiǎo jiù jīngcháng gēn bàba pǎobù, pǎobù néng ràng rén kuàilè."}, {"speaker": "白家月 (Bạch Gia Nguyệt)", "cn": "好,那我准备一下。", "pinyin": "Hǎo, nà wǒ zhǔnbèi yíxià."}, {"speaker": "李文 (Lý Văn)", "cn": "我现在坐地铁去找你,一会儿楼下见。", "pinyin": "Wǒ xiànzài zuò dìtiě qù zhǎo nǐ, yíhuìr lóu xià jiàn."}], "translation_vn": "Lý Văn: A lô, Gia Nguyệt à, hôm nay thời tiết khá đẹp, chúng ta đi chạy bộ nhé? Bạch Gia Nguyệt: Bạn chạy nhanh hơn mình, chúng ta có thể chạy cùng nhau không? Lý Văn: Được mà, mình sẽ chạy chầm chậm đợi bạn. Bạch Gia Nguyệt: Được. Bạn đúng là mê chạy bộ thật đấy! Lý Văn: Từ nhỏ mình đã thường xuyên chạy bộ cùng bố rồi. Chạy bộ khiến con người ta thấy sảng khoái hẳn ra. Bạch Gia Nguyệt: Ừ, vậy để mình chuẩn bị một chút. Lý Văn: Bây giờ mình đi tàu điện ngầm qua chỗ bạn, lát nữa gặp nhau ở dưới tầng nhé.", "audio_dialogue": "12-5 @xitoytili_luoluodafang.mp3", "audio_vocab": "12-6 @xitoytili_luoluodafang.mp3"}, {"label": "Bài khóa 4", "type": "passage", "lines": [{"speaker": "", "cn": "前几天天气不好,我没走路,每天坐两站地铁去学校。今天是个大晴天,李文让我跟他去外面跑步。他小时候经常跑步,跑得比我快,但是他会等我。跟李文一起跑步,我好高兴啊!", "pinyin": "Qián jǐ tiān tiānqì bù hǎo, wǒ méi zǒulù, měi tiān zuò liǎng zhàn dìtiě qù xuéxiào. Jīntiān shì ge dà qíngtiān, Lǐ Wén ràng wǒ gēn tā qù wàimiàn pǎobù. Tā xiǎoshíhou jīngcháng pǎobù, pǎo de bǐ wǒ kuài, dànshì tā huì děng wǒ. Gēn Lǐ Wén yìqǐ pǎobù, wǒ hǎo gāoxìng a!"}], "translation_vn": "Mấy hôm trước thời tiết xấu, tôi không đi bộ mà mỗi ngày đều đi hai trạm tàu điện ngầm để đến trường. Hôm nay trời quang đãng, Lý Văn bảo tôi cùng bạn ấy ra ngoài chạy bộ. Hồi nhỏ, bạn ấy thường xuyên chạy bộ, chạy nhanh hơn tôi, nhưng bạn ấy sẽ đợi tôi. Chạy bộ cùng Lý Văn tôi thấy rất vui!", "audio_dialogue": "12-7 @xitoytili_luoluodafang.mp3", "audio_vocab": "12-8 @xitoytili_luoluodafang.mp3"}]}, {"id": 13, "title_cn": "我们爱上中文课", "title_pinyin": "Wǒmen ài shàng Zhōngwén kè", "title_vn": "Chúng tôi yêu thích môn tiếng Trung Quốc", "goals": ["能听懂并使用比较句说明事物之间的具体差别。Có thể nghe hiểu và sử dụng được câu so sánh để nói rõ sự khác biệt cụ thể giữa các sự vật.", "能听懂并使用比较句说明事物之间的差别很小。Có thể nghe hiểu và sử dụng được câu so sánh để nói rõ về sự khác biệt nhỏ giữa các sự vật.", "掌握双宾语句的用法，能表达给予的意思。Nắm vững cách dùng của câu có hai tân ngữ để diễn đạt ý nghĩa cho, tặng."], "vocab": [{"hanzi": "新年", "pinyin": "xīnnián", "pos": "dt.", "vn": "năm mới"}, {"hanzi": "教", "pinyin": "jiāo", "pos": "đgt.", "vn": "dạy"}, {"hanzi": "花", "pinyin": "huā", "pos": "dt.", "vn": "hoa"}, {"hanzi": "希望", "pinyin": "xīwàng", "pos": "đgt.", "vn": "hy vọng, mong muốn"}, {"hanzi": "上面", "pinyin": "shàngmiàn", "pos": "dt.", "vn": "phía trên, bên trên"}, {"hanzi": "洗手间", "pinyin": "xǐshǒujiān", "pos": "dt.", "vn": "nhà vệ sinh"}, {"hanzi": "里面", "pinyin": "lǐmiàn", "pos": "dt.", "vn": "bên trong"}, {"hanzi": "笔", "pinyin": "bǐ", "pos": "lượng.", "vn": "nét, nét bút"}, {"hanzi": "可能", "pinyin": "kěnéng", "pos": "đgt.", "vn": "có thể, có lẽ"}, {"hanzi": "上网", "pinyin": "shàngwǎng", "pos": "đgt.", "vn": "lên mạng"}, {"hanzi": "那样", "pinyin": "nàyàng", "pos": "dt.", "vn": "như vậy, thế kia"}, {"hanzi": "告诉", "pinyin": "gàosu", "pos": "đgt.", "vn": "nói cho biết, kể"}, {"hanzi": "班", "pinyin": "bān", "pos": "dt.", "vn": "lớp"}], "grammar": [{"title": "双宾语句 (2) Câu có hai tân ngữ (2)", "explanation_vn": "Câu có hai tân ngữ là câu mà động từ mang hai tân ngữ, thông thường tân ngữ thứ nhất chỉ người, tân ngữ thứ hai chỉ sự vật. Trong bài này, câu hai tân ngữ được tạo bởi các động từ \"拿\", \"送\", \"卖\" với \"给\".", "examples": [{"cn": "王老师喜欢花，就送给她花吧。", "pinyin": "Wáng lǎoshī xǐhuan huā, jiù sòng gěi tā huā ba.", "vn": ""}, {"cn": "她拿给我一杯水。", "pinyin": "Tā ná gěi wǒ yì bēi shuǐ.", "vn": ""}, {"cn": "他卖给我一本中文书。", "pinyin": "Tā mài gěi wǒ yì běn Zhōngwén shū.", "vn": ""}]}, {"title": "比较句 (7) Câu so sánh (7)", "explanation_vn": "Trong câu so sánh sử dụng \"比\", cụm từ chỉ số lượng được đặt sau tính từ để biểu thị sự khác biệt cụ thể. Cấu trúc cơ bản: A bỉ B + tính từ + cụm từ chỉ số lượng.", "examples": [{"cn": "今天的词比昨天多了十个。", "pinyin": "Jīntiān de cí bǐ zuótiān duō le shí ge.", "vn": ""}, {"cn": "姐姐比我大三岁。", "pinyin": "Jiějie bǐ wǒ dà sān suì.", "vn": ""}, {"cn": "坐飞机比坐火车快五个多小时。", "pinyin": "Zuò fēijī bǐ zuò huǒchē kuài wǔ ge duō xiǎoshí.", "vn": ""}]}, {"title": "比较句 (8) Câu so sánh (8)", "explanation_vn": "Trong câu so sánh dùng \"比\", \"一点儿\" hoặc \"一些\" được đặt sau tính từ để biểu thị sự khác biệt không lớn. Cấu trúc cơ bản: A bỉ B + tính từ + 一点儿/一些.", "examples": [{"cn": "比我们一起买的那个本子贵一点儿。", "pinyin": "Bǐ wǒmen yìqǐ mǎi de nàge běnzi guì yìdiǎnr.", "vn": ""}, {"cn": "姐姐比我高一点儿。", "pinyin": "Jiějie bǐ wǒ gāo yìdiǎnr.", "vn": ""}, {"cn": "那间教室比这间大一些。", "pinyin": "Nà jiān jiàoshì bǐ zhè jiān dà yìxiē.", "vn": ""}]}], "texts": [{"label": "Bài khóa 1", "type": "dialogue", "lines": [{"speaker": "Bạch Gia Nguyệt", "cn": "时间过得真快啊！新年就要到了。", "pinyin": "Shíjiān guò de zhēn kuài a! Xīnnián jiù yào dào le."}, {"speaker": "Trần Thiên Trung", "cn": "这一年王老师教我们中文，每天工作都很累。", "pinyin": "Zhè yì nián Wáng lǎoshī jiāo wǒmen Zhōngwén, měitiān gōngzuò dōu hěn lèi."}, {"speaker": "Bạch Gia Nguyệt", "cn": "是啊，她教得很好。因为她，我们都非常爱上中文课。", "pinyin": "Shì a, tā jiāo de hěn hǎo. Yīnwèi tā, wǒmen dōu fēicháng ài shàng Zhōngwén kè."}, {"speaker": "Trần Thiên Trung", "cn": "我们给她准备个新年礼物吧。你觉得送给她什么好呢？", "pinyin": "Wǒmen gěi tā zhǔnbèi ge xīnnián lǐwù ba. Nǐ juéde sòng gěi tā shénme hǎo ne?"}, {"speaker": "Bạch Gia Nguyệt", "cn": "王老师喜欢花，就送给她花吧。", "pinyin": "Wáng lǎoshī xǐhuan huā, jiù sòng gěi tā huā ba."}, {"speaker": "Trần Thiên Trung", "cn": "那我们去花店看看，现在买花的人多，希望花店还有漂亮的花。", "pinyin": "Nà wǒmen qù huādiàn kànkan, xiànzài mǎi huā de rén duō, xīwàng huādiàn hái yǒu piàoliang de huā."}], "translation_vn": "Bạch Gia Nguyệt: Thời gian trôi nhanh thật đấy! Sắp đến năm mới rồi. Trần Thiên Trung: Một năm nay, cô Vương dạy chúng ta tiếng Trung Quốc, ngày nào làm việc cũng đều rất mệt. Bạch Gia Nguyệt: Đúng vậy, cô dạy rất hay. Nhờ có cô mà chúng ta ai cũng yêu thích môn tiếng Trung Quốc. Trần Thiên Trung: Chúng ta hãy chuẩn bị một món quà năm mới tặng cô nhé. Bạn thấy tặng cô quà gì thì hợp nhỉ? Bạch Gia Nguyệt: Cô Vương thích hoa đấy, cứ tặng hoa cho cô đi. Trần Thiên Trung: Vậy chúng ta ra cửa hàng hoa xem thử. Bây giờ người mua hoa rất đông, hy vọng ở đó vẫn còn hoa đẹp.", "audio_dialogue": "13-1 @xitoytili_luoluodafang.mp3", "audio_vocab": "13-2 @xitoytili_luoluodafang.mp3"}, {"label": "Bài khóa 2", "type": "dialogue", "lines": [{"speaker": "Bạch Gia Nguyệt", "cn": "王老师，今天的词语比昨天多了十个。", "pinyin": "Wáng lǎoshī, jīntiān de cíyǔ bǐ zuótiān duō le shí ge."}, {"speaker": "Vương Nhất Phi", "cn": "是啊！你们都学会了吗？", "pinyin": "Shì a! Nǐmen dōu xuéhuì le ma?"}, {"speaker": "Annie", "cn": "学会了，没有问题。", "pinyin": "Xuéhuì le, méiyǒu wèntí."}, {"speaker": "Vương Nhất Phi", "cn": "好。现在我来说，你们在本子上面写。", "pinyin": "Hǎo. Xiànzài wǒ lái shuō, nǐmen zài běnzi shàngmiàn xiě."}, {"speaker": "Vương Nhất Phi", "cn": "同学们，\"洗手间\"的\"间\"字写错了，它的里面是\"日\"，不是\"口\"。", "pinyin": "Tóngxuémen, \"xǐshǒujiān\" de \"jiān\" zì xiěcuò le, tā de lǐmiàn shì \"rì\", bú shì \"kǒu\"."}, {"speaker": "Bạch Gia Nguyệt", "cn": "\"日\"比\"口\"多一笔，写\"口\"就是\"问题\"的\"问\"了。", "pinyin": "\"Rì\" bǐ \"kǒu\" duō yì bǐ, xiě \"kǒu\" jiù shì \"wèntí\" de \"wèn\" le."}, {"speaker": "Vương Nhất Phi", "cn": "没错，你说得很对。", "pinyin": "Méi cuò, nǐ shuō de hěn duì."}], "translation_vn": "Bạch Gia Nguyệt: Cô Vương ơi, từ mới của ngày hôm nay nhiều hơn hôm qua mười từ ạ. Vương Nhất Phi: Đúng vậy! Các em đã nắm được hết chưa? Annie: Dạ, chúng em đã nắm được rồi ạ, không có vấn đề gì đâu ạ. Vương Nhất Phi: Tốt. Bây giờ cô sẽ đọc, các em viết vào vở nhé. Vương Nhất Phi: Các em ơi, chữ \"间\" trong từ \"洗手间\" viết sai rồi, bên trong nó là chữ \"日\" (nhật) chứ không phải chữ \"口\" (khẩu) đâu nhé. Bạch Gia Nguyệt: Chữ \"日\" nhiều hơn chữ \"口\" một nét, nếu viết thành \"口\" thì sẽ thành chữ \"问\" trong từ \"问题\" rồi ạ. Vương Nhất Phi: Đúng rồi, em nói rất chính xác.", "audio_dialogue": "13-3 @xitoytili_luoluodafang.mp3", "audio_vocab": "13-4 @xitoytili_luoluodafang.mp3"}, {"label": "Bài khóa 3", "type": "dialogue", "lines": [{"speaker": "Annie", "cn": "家月，你觉得这个本子怎么样？", "pinyin": "Jiāyuè, nǐ juéde zhège běnzi zěnmeyàng?"}, {"speaker": "Bạch Gia Nguyệt", "cn": "很漂亮，多少钱一个？", "pinyin": "Hěn piàoliang, duōshao qián yí ge?"}, {"speaker": "Annie", "cn": "比我们一起买的那个本子贵一点儿。", "pinyin": "Bǐ wǒmen yìqǐ mǎi de nàge běnzi guì yìdiǎnr."}, {"speaker": "Bạch Gia Nguyệt", "cn": "这么漂亮的本子，不可能贵一点儿吧？", "pinyin": "Zhème piàoliang de běnzi, bù kěnéng guì yìdiǎnr ba?"}, {"speaker": "Annie", "cn": "我是上网买的，真没那么贵。我买了两个，送你一个。", "pinyin": "Wǒ shì shàngwǎng mǎi de, zhēn méi nàme guì. Wǒ mǎile liǎng ge, sòng nǐ yí ge."}, {"speaker": "Bạch Gia Nguyệt", "cn": "谢谢！那我送给你什么呢？", "pinyin": "Xièxie! Nà wǒ sòng gěi nǐ shénme ne?"}, {"speaker": "Annie", "cn": "咖啡杯吧。我最喜欢喝咖啡了。", "pinyin": "Kāfēibēi ba. Wǒ zuì xǐhuan hē kāfēi le."}, {"speaker": "Bạch Gia Nguyệt", "cn": "好，那样我们就都有新年礼物了！", "pinyin": "Hǎo, nàyàng wǒmen jiù dōu yǒu xīnnián lǐwù le!"}], "translation_vn": "Annie: Gia Nguyệt, bạn thấy cuốn vở này thế nào? Bạch Gia Nguyệt: Rất đẹp. Bao nhiêu tiền một cuốn vậy? Annie: Đắt hơn hôm trước mà chúng ta cùng đi mua một chút. Bạch Gia Nguyệt: Cuốn vở đẹp thế này, không thể chỉ đắt hơn một chút nhỉ? Annie: Mình mua trên mạng đấy, thật sự không đắt đến thế đâu. Mình mua hai cuốn, tặng bạn một cuốn này. Bạch Gia Nguyệt: Cảm ơn nhé! Vậy mình nên tặng lại bạn cái gì đây? Annie: Tặng cốc uống cà phê đi, mình thích uống cà phê nhất. Bạch Gia Nguyệt: Được, như vậy là chúng ta ai cũng đều có quà năm mới rồi!", "audio_dialogue": "13-5 @xitoytili_luoluodafang.mp3", "audio_vocab": "13-6 @xitoytili_luoluodafang.mp3"}, {"label": "Bài khóa 4", "type": "passage", "lines": [{"speaker": "", "cn": "新年就要到了，安妮送给我一个新本子。她告诉我是在网上买的，比我的本子贵一点儿。我们班同学也送了王老师漂亮的花，希望她高高兴兴地过个新年。", "pinyin": "Xīnnián jiù yào dào le, Ānnī sòng gěi wǒ yí ge xīn běnzi. Tā gàosu wǒ shì zài wǎngshàng mǎi de, bǐ wǒ de běnzi guì yìdiǎnr. Wǒmen bān tóngxué yě sòngle Wáng lǎoshī piàoliang de huā, xīwàng tā gāogāoxìngxìng de guò ge xīnnián."}], "translation_vn": "Sắp năm mới rồi, Annie tặng tôi một cuốn vở mới. Bạn ấy kể với tôi là mua trên mạng, đắt hơn cuốn của tôi một chút. Các bạn trong lớp cũng tặng cô Vương những bông hoa đẹp, hy vọng cô vui vẻ đón một năm mới thật vui.", "audio_dialogue": "13-7 @xitoytili_luoluodafang.mp3", "audio_vocab": "13-8 @xitoytili_luoluodafang.mp3"}]}, {"id": 14, "title_cn": "一个人过年多没意思啊", "title_pinyin": "Yí gè rén guònián duō méi yìsi a", "title_vn": "Một mình đón năm mới thì thật vô vị", "goals": ["能听懂并描述某处存在某人或某物。Có thể nghe hiểu và miêu tả một ai đó hoặc vật gì đó đang tồn tại ở nơi nào đó.", "能听懂并使用复合趋向补语表达动作的方向。Có thể nghe hiểu và sử dụng được bổ ngữ xu hướng kép để diễn đạt phương hướng của động tác.", "掌握程度副词\"多\"的用法，能表达程度很高的意思。Nắm vững cách dùng của phó từ chỉ mức độ \"多\" để diễn đạt ý nghĩa mức độ rất cao."], "vocab": [{"hanzi": "站", "pinyin": "zhàn", "pos": "đgt.", "vn": "đứng"}, {"hanzi": "包", "pinyin": "bāo", "pos": "dt./đgt./lượng.", "vn": "túi, gói, bao"}, {"hanzi": "过年", "pinyin": "guònián", "pos": "đgt.", "vn": "đón Tết, ăn Tết"}, {"hanzi": "没意思", "pinyin": "méi yìsi", "pos": "", "vn": "vô vị, chán"}, {"hanzi": "位", "pinyin": "wèi", "pos": "lượng.", "vn": "người (cách gọi lịch sự)"}, {"hanzi": "前面", "pinyin": "qiánmiàn", "pos": "dt.", "vn": "phía trước"}, {"hanzi": "房子", "pinyin": "fángzi", "pos": "dt.", "vn": "nhà, ngôi nhà, căn hộ"}, {"hanzi": "小孩儿", "pinyin": "xiǎoháir", "pos": "dt.", "vn": "đứa trẻ, trẻ con"}, {"hanzi": "女孩儿", "pinyin": "nǚháir", "pos": "dt.", "vn": "bé gái, cô bé"}, {"hanzi": "姓", "pinyin": "xìng", "pos": "đgt.", "vn": "họ"}, {"hanzi": "眼睛", "pinyin": "yǎnjing", "pos": "dt.", "vn": "mắt"}, {"hanzi": "跳舞", "pinyin": "tiàowǔ", "pos": "đgt.", "vn": "nhảy múa, khiêu vũ"}], "grammar": [{"title": "存现句 (2) Câu tồn hiện (2)", "explanation_vn": "Trợ từ động thái \"着\" đặt sau động từ có thể tạo thành câu tồn hiện, phía trước động từ là cụm từ chỉ nơi chốn, phía sau thường là người hoặc sự vật không xác định. Cấu trúc cơ bản: Từ/cụm từ chỉ nơi chốn + động từ + 着 + người/sự vật.", "examples": [{"cn": "你家楼下站着一个人。", "pinyin": "Nǐ jiā lóu xià zhànzhe yí ge rén.", "vn": ""}, {"cn": "爸爸手里拿着一杯咖啡。", "pinyin": "Bàba shǒu lǐ názhe yì bēi kāfēi.", "vn": ""}, {"cn": "我们教室里坐着不少学生。", "pinyin": "Wǒmen jiàoshì lǐ zuòzhe bùshǎo xuésheng.", "vn": ""}]}, {"title": "程度副词\"多\" Phó từ chỉ mức độ \"多\"", "explanation_vn": "\"多\" dùng trong câu cảm thán để biểu thị mức độ rất cao.", "examples": [{"cn": "你一个人在这儿多没意思啊！", "pinyin": "Nǐ yí gè rén zài zhèr duō méi yìsi a!", "vn": ""}, {"cn": "我们一起去多好啊！", "pinyin": "Wǒmen yìqǐ qù duō hǎo a!", "vn": ""}, {"cn": "多好看啊！买这件吧。", "pinyin": "Duō hǎokàn a! Mǎi zhè jiàn ba.", "vn": ""}]}, {"title": "复合趋向补语 Bổ ngữ xu hướng kép", "explanation_vn": "\"上\", \"下\", \"进\", \"出\", \"回\", \"过\" kết hợp với \"来/去\" và cụm từ \"起来\" đều đặt sau động từ để tạo thành bổ ngữ xu hướng kép, biểu thị phương hướng của động tác. Khi động từ mang tân ngữ, có hai trường hợp: (1) tân ngữ là danh từ chỉ địa điểm, đặt trước \"来/去\"; (2) tân ngữ là danh từ chỉ sự vật, đặt trước hoặc sau \"来/去\" đều được.", "examples": [{"cn": "她经常跑上来找我玩。", "pinyin": "Tā jīngcháng pǎo shànglái zhǎo wǒ wán.", "vn": ""}, {"cn": "楼不高，我们走上去吧。", "pinyin": "Lóu bù gāo, wǒmen zǒu shàngqù ba.", "vn": ""}, {"cn": "一听到老师叫他的名字，他就站起来了。", "pinyin": "Yì tīngdào lǎoshī jiào tā de míngzi, tā jiù zhàn qǐlái le.", "vn": ""}, {"cn": "同学们都走进教室去了。", "pinyin": "Tóngxuémen dōu zǒujìn jiàoshì qù le.", "vn": ""}, {"cn": "妈妈让我买回一些菜来。", "pinyin": "Māma ràng wǒ mǎihuí yìxiē cài lái.", "vn": ""}, {"cn": "白家月从书包里拿出来一个漂亮的本子。", "pinyin": "Bái Jiāyuè cóng shūbāo lǐ náchūlái yí ge piàoliang de běnzi.", "vn": ""}]}], "texts": [{"label": "Bài khóa 1", "type": "dialogue", "lines": [{"speaker": "Lý Văn", "cn": "王老师，你家楼下站着一个人。", "pinyin": "Wáng lǎoshī, nǐ jiā lóu xià zhànzhe yí ge rén."}, {"speaker": "Vương Nhất Phi", "cn": "我家楼下？我看看。", "pinyin": "Wǒ jiā lóu xià? Wǒ kànkan."}, {"speaker": "Lý Văn", "cn": "那个人穿着黑色的裤子，手里还拿着一个黑色的包。", "pinyin": "Nàge rén chuānzhe hēisè de kùzi, shǒu lǐ hái názhe yí ge hēisè de bāo."}, {"speaker": "Vương Nhất Phi", "cn": "我看见那个人了，他是我男朋友。", "pinyin": "Wǒ kànjiàn nàge rén le, tā shì wǒ nánpéngyou."}, {"speaker": "Lý Văn", "cn": "那我们快过去吧。", "pinyin": "Nà wǒmen kuài guòqù ba."}], "translation_vn": "Lý Văn: Cô Vương ơi, ở dưới tầng nhà cô có một người đang đứng kia. Vương Nhất Phi: Dưới tầng nhà cô á? Để cô xem nào. Lý Văn: Người đó mặc chiếc quần màu đen, trên tay còn đang cầm một chiếc túi màu đen nữa. Vương Nhất Phi: Cô nhìn thấy người đó rồi, anh ấy là bạn trai của cô. Lý Văn: Vậy chúng ta mau qua đó đi.", "audio_dialogue": "14-1 @xitoytili_luoluodafang.mp3", "audio_vocab": "14-2 @xitoytili_luoluodafang.mp3"}, {"label": "Bài khóa 2", "type": "dialogue", "lines": [{"speaker": "Vương Nhất Phi", "cn": "同乐，真是你啊！上次打电话，你说有时间过来看我，没想到这么快就来了。", "pinyin": "Tóngyuè, zhēn shì nǐ a! Shàng cì dǎ diànhuà, nǐ shuō yǒu shíjiān guòlái kàn wǒ, méi xiǎngdào zhème kuài jiù lái le."}, {"speaker": "Dương Đồng Lạc", "cn": "就要过年了，你一个人在这儿多没意思啊，所以我就早早过来了。", "pinyin": "Jiù yào guònián le, nǐ yí gè rén zài zhèr duō méi yìsi a, suǒyǐ wǒ jiù zǎozǎo guòlái le."}, {"speaker": "Vương Nhất Phi", "cn": "你能来，我太高兴了！", "pinyin": "Nǐ néng lái, wǒ tài gāoxìng le!"}, {"speaker": "Dương Đồng Lạc", "cn": "一飞，你旁边这位是？", "pinyin": "Yīfēi, nǐ pángbiān zhè wèi shì?"}, {"speaker": "Vương Nhất Phi", "cn": "同乐，这是李文，他在我们学校学医。李文，这是我男朋友杨同乐。", "pinyin": "Tóngyuè, zhè shì Lǐ Wén, tā zài wǒmen xuéxiào xué yī. Lǐ Wén, zhè shì wǒ nánpéngyou Yáng Tóngyuè."}, {"speaker": "Dương Đồng Lạc", "cn": "李文，很高兴认识你！", "pinyin": "Lǐ Wén, hěn gāoxìng rènshi nǐ!"}, {"speaker": "Lý Văn", "cn": "认识你我也很高兴！我家就在前面那个楼，有时间来玩。", "pinyin": "Rènshi nǐ wǒ yě hěn gāoxìng! Wǒ jiā jiù zài qiánmiàn nàge lóu, yǒu shíjiān lái wán."}], "translation_vn": "Vương Nhất Phi: Đồng Lạc, đúng là anh rồi! Lần trước gọi điện, anh nói lúc nào rảnh sẽ đến thăm em, không ngờ anh lại đến nhanh thế này! Dương Đồng Lạc: Sắp đến Tết rồi, em ở đây một mình thì thật vô vị, nên anh đến sớm một chút. Vương Nhất Phi: Anh đến được em vui quá! Dương Đồng Lạc: Nhất Phi, bạn bên cạnh em là ai vậy? Vương Nhất Phi: Đồng Lạc ơi, đây là Lý Văn, em ấy học ngành y ở trường em. Lý Văn, đây là bạn trai của em, anh Dương Đồng Lạc. Dương Đồng Lạc: Chào Lý Văn, rất vui được làm quen với em! Lý Văn: Em cũng rất vui được quen biết anh! Nhà em ở ngay toà nhà phía trước kia, lúc nào rảnh anh qua chơi nhé.", "audio_dialogue": "14-3 @xitoytili_luoluodafang.mp3", "audio_vocab": "14-4 @xitoytili_luoluodafang.mp3"}, {"label": "Bài khóa 3", "type": "dialogue", "lines": [{"speaker": "Dương Đồng Lạc", "cn": "一飞，你住的房子真不错，很大，离学校也不远。", "pinyin": "Yīfēi, nǐ zhù de fángzi zhēn búcuò, hěn dà, lí xuéxiào yě bù yuǎn."}, {"speaker": "Vương Nhất Phi", "cn": "是啊！我楼下还住着一家中国人，他们人很好。", "pinyin": "Shì a! Wǒ lóu xià hái zhùzhe yì jiā Zhōngguórén, tāmen rén hěn hǎo."}, {"speaker": "Dương Đồng Lạc", "cn": "这样你有事情就可以找他们帮忙。", "pinyin": "Zhèyàng nǐ yǒu shìqing jiù kěyǐ zhǎo tāmen bāngmáng."}, {"speaker": "Vương Nhất Phi", "cn": "对，我也帮他们家的小孩儿学中文。", "pinyin": "Duì, wǒ yě bāng tāmen jiā de xiǎoháir xué Zhōngwén."}, {"speaker": "Dương Đồng Lạc", "cn": "我记得你跟我说过，是个女孩儿，学得也很好。", "pinyin": "Wǒ jìde nǐ gēn wǒ shuōguo, shì ge nǚháir, xué de yě hěn hǎo."}, {"speaker": "Vương Nhất Phi", "cn": "没错，她经常跑上来我这儿玩。", "pinyin": "Méi cuò, tā jīngcháng pǎo shànglái wǒ zhèr wán."}, {"speaker": "Dương Đồng Lạc", "cn": "你问问他们什么时候有时间，我请他们吃个饭。", "pinyin": "Nǐ wènwen tāmen shénme shíhou yǒu shíjiān, wǒ qǐng tāmen chī ge fàn."}], "translation_vn": "Dương Đồng Lạc: Nhất Phi, căn hộ em ở thật đẹp, rộng rãi, lại không xa trường học. Vương Nhất Phi: Vâng ạ! Dưới tầng nhà em còn có một gia đình người Trung Quốc sinh sống, họ rất tốt bụng. Dương Đồng Lạc: Như vậy thì khi em có việc gì có thể nhờ họ giúp đỡ. Vương Nhất Phi: Đúng vậy, em cũng đang giúp con họ học tiếng Trung Quốc. Dương Đồng Lạc: Anh nhớ em đã từng kể với anh rồi, là một bé gái, học cũng rất giỏi. Vương Nhất Phi: Vâng, con bé thường xuyên lên đây chơi với em. Dương Đồng Lạc: Em hỏi xem khi nào họ rảnh, anh muốn mời họ ăn một bữa cơm.", "audio_dialogue": "14-5.mp3", "audio_vocab": "14-6 @xitoytili_luoluodafang.mp3"}, {"label": "Bài khóa 4", "type": "passage", "lines": [{"speaker": "", "cn": "我男朋友姓杨，叫杨同乐。他高个子、大眼睛、唱歌唱得很好，跳舞跳得也不错。他和我姐姐一起工作，是姐姐介绍我们认识的。他告诉我，从见到我的第一天开始，他就喜欢上我了。", "pinyin": "Wǒ nánpéngyou xìng Yáng, jiào Yáng Tónglè. Tā gāo gèzi, dà yǎnjing, chànggē chàng de hěn hǎo, tiàowǔ tiào de yě búcuò. Tā hé wǒ jiějie yìqǐ gōngzuò, shì jiějie jièshào wǒmen rènshi de. Tā gàosu wǒ, cóng jiàndào wǒ de dì-yī tiān kāishǐ, tā jiù xǐhuanshàng wǒ le."}], "translation_vn": "Bạn trai tôi họ Dương, tên là Dương Đồng Lạc. Anh ấy có dáng người cao, mắt to, hát rất hay và nhảy cũng rất đẹp. Anh ấy làm việc cùng với chị gái tôi, chị chính là người đã giới thiệu chúng tôi quen nhau. Anh ấy kể với tôi rằng, ngay từ ngày đầu tiên gặp tôi, anh ấy đã đem lòng yêu mến tôi rồi.", "audio_dialogue": "14-7 @xitoytili_luoluodafang.mp3", "audio_vocab": "14-8 @xitoytili_luoluodafang.mp3"}]}, {"id": 15, "title_cn": "我想再去一次中国", "title_pinyin": "Wǒ xiǎng zài qù yí cì Zhōngguó", "title_vn": "Em muốn đi Trung Quốc một lần nữa", "goals": ["能听懂并谈论旅游的计划。Có thể nghe hiểu và thảo luận được kế hoạch du lịch.", "能听懂并使用动量补语表达动作或事情发生的次数。Có thể nghe hiểu và sử dụng được bổ ngữ động lượng để diễn đạt số lần phát sinh của động tác hoặc sự việc.", "掌握\"有\"字句(2)的用法，能说明达到了一定的数量。Nắm vững cách dùng của câu chữ \"有\"(2) để nói rõ về việc đạt tới một số lượng nhất định."], "vocab": [{"hanzi": "姓名", "pinyin": "xìngmíng", "pos": "dt.", "vn": "họ tên"}, {"hanzi": "出国", "pinyin": "chūguó", "pos": "đgt.", "vn": "ra nước ngoài, xuất ngoại"}, {"hanzi": "门票", "pinyin": "ménpiào", "pos": "dt.", "vn": "vé vào cửa"}, {"hanzi": "高中", "pinyin": "gāozhōng", "pos": "dt.", "vn": "cấp ba, trung học phổ thông"}, {"hanzi": "出门", "pinyin": "chūmén", "pos": "đgt.", "vn": "ra ngoài, rời nhà"}, {"hanzi": "路", "pinyin": "lù", "pos": "dt.", "vn": "con đường"}, {"hanzi": "颐和园", "pinyin": "Yíhéyuán", "pos": "danh từ riêng", "vn": "Di Hoà Viên (ở Bắc Kinh)"}, {"hanzi": "机场", "pinyin": "jīchǎng", "pos": "dt.", "vn": "sân bay"}, {"hanzi": "机票", "pinyin": "jīpiào", "pos": "dt.", "vn": "vé máy bay"}, {"hanzi": "飞", "pinyin": "fēi", "pos": "đgt.", "vn": "bay"}, {"hanzi": "好像", "pinyin": "hǎoxiàng", "pos": "đgt.", "vn": "dường như, giống như, hình như"}, {"hanzi": "鸟", "pinyin": "niǎo", "pos": "dt.", "vn": "con chim"}], "grammar": [{"title": "动量补语 (1) Bổ ngữ động lượng (1)", "explanation_vn": "\"Số từ + 次\" đặt sau động từ để tạo thành bổ ngữ động lượng, biểu thị số lần xảy ra của động tác. Khi tân ngữ của động từ là tên người hoặc địa danh thì có thể đặt trước hoặc sau bổ ngữ động lượng.", "examples": [{"cn": "我想去中国，虽然去过一次，但是很想再去一次。", "pinyin": "Wǒ xiǎng qù Zhōngguó, suīrán qùguo yí cì, dànshì hěn xiǎng zài qù yí cì.", "vn": ""}, {"cn": "安妮去过一次北京。", "pinyin": "Ānnī qùguo yí cì Běijīng.", "vn": ""}, {"cn": "李文见了杨同乐两次。", "pinyin": "Lǐ Wén jiànle Yáng Tóngyuè liǎng cì.", "vn": ""}]}, {"title": "动量补语 (2) Bổ ngữ động lượng (2)", "explanation_vn": "Khi động từ vừa mang bổ ngữ động lượng vừa mang tân ngữ, nếu tân ngữ là danh từ chỉ sự vật thì thường đặt sau bổ ngữ động lượng; nếu tân ngữ là đại từ thì đặt trước bổ ngữ động lượng.", "examples": [{"cn": "因为我想再吃一次烤鸭，再喝一次奶茶。", "pinyin": "Yīnwèi wǒ xiǎng zài chī yí cì kǎoyā, zài hē yí cì nǎichá.", "vn": ""}, {"cn": "我想找他一次。", "pinyin": "Wǒ xiǎng zhǎo tā yí cì.", "vn": ""}, {"cn": "安妮来过这儿两次。", "pinyin": "Ānnī láiguo zhèr liǎng cì.", "vn": ""}]}, {"title": "\"有\"字句 (2) Câu chữ \"有\" (2)", "explanation_vn": "\"有 + cụm từ chỉ số lượng\" biểu thị sự việc đạt đến một số lượng nhất định.", "examples": [{"cn": "你有一年没回国了吧？", "pinyin": "Nǐ yǒu yì nián méi huí guó le ba?", "vn": ""}, {"cn": "你女儿今年有10岁了吗？", "pinyin": "Nǐ nǚ'ér jīnnián yǒu shí suì le ma?", "vn": ""}, {"cn": "我有一个月没给家里打电话了。", "pinyin": "Wǒ yǒu yí ge yuè méi gěi jiā lǐ dǎ diànhuà le.", "vn": ""}]}], "texts": [{"label": "Bài khóa 1", "type": "dialogue", "lines": [{"speaker": "Vương Nhất Phi", "cn": "考试就要开始了，请大家写上姓名，写好后就可以做题了。", "pinyin": "Kǎoshì jiù yào kāishǐ le, qǐng dàjiā xiěshàng xìngmíng, xiěhǎo hòu jiù kěyǐ zuò tí le."}, {"speaker": "Bạch Gia Nguyệt", "cn": "老师，我做完了。", "pinyin": "Lǎoshī, wǒ zuòwán le."}, {"speaker": "Trần Thiên Trung", "cn": "老师，我也做完了。", "pinyin": "Lǎoshī, wǒ yě zuòwán le."}, {"speaker": "Vương Nhất Phi", "cn": "……对了，你们考完试想做什么？", "pinyin": "Duìle, nǐmen kǎowán shì xiǎng zuò shénme?"}, {"speaker": "Bạch Gia Nguyệt", "cn": "我很想去中国，虽然去过一次，但是很想再去一次。", "pinyin": "Wǒ hěn xiǎng qù Zhōngguó, suīrán qùguo yí cì, dànshì hěn xiǎng zài qù yí cì."}, {"speaker": "Vương Nhất Phi", "cn": "不错，到中国后你就可以经常说中文了。", "pinyin": "Búcuò, dào Zhōngguó hòu nǐ jiù kěyǐ jīngcháng shuō Zhōngwén le."}], "translation_vn": "Vương Nhất Phi: Sắp bắt đầu vào giờ thi rồi, mời các em viết họ tên mình vào, viết xong là có thể làm bài. Bạch Gia Nguyệt: Thưa cô, em làm xong rồi ạ. Trần Thiên Trung: Thưa cô, em cũng làm xong rồi ạ. Vương Nhất Phi: Đúng rồi, thi xong các em muốn làm gì? Bạch Gia Nguyệt: Em rất muốn đi Trung Quốc, tuy đã từng đi một lần rồi nhưng em rất muốn đi thêm một lần nữa. Vương Nhất Phi: Tốt lắm, sau khi đến Trung Quốc em có thể thường xuyên nói tiếng Trung Quốc rồi.", "audio_dialogue": "15-1 @xitoytili_luoluodafang.mp3", "audio_vocab": "15-2 @xitoytili_luoluodafang.mp3"}, {"label": "Bài khóa 2", "type": "dialogue", "lines": [{"speaker": "Bạch Gia Nguyệt", "cn": "考完试了，我现在可以出国旅游了。", "pinyin": "Kǎowán shì le, wǒ xiànzài kěyǐ chūguó lǚyóu le."}, {"speaker": "Lý Văn", "cn": "你要去哪儿？", "pinyin": "Nǐ yào qù nǎr?"}, {"speaker": "Bạch Gia Nguyệt", "cn": "我要再去一次北京。", "pinyin": "Wǒ yào zài qù yí cì Běijīng."}, {"speaker": "Lý Văn", "cn": "为什么还去北京？", "pinyin": "Wèi shénme hái qù Běijīng?"}, {"speaker": "Bạch Gia Nguyệt", "cn": "因为我想再吃一次烤鸭，再喝一次奶茶，再去北京大学看一次电影……", "pinyin": "Yīnwèi wǒ xiǎng zài chī yí cì kǎoyā, zài hē yí cì nǎichá, zài qù Běijīng Dàxué kàn yí cì diànyǐng……"}, {"speaker": "Lý Văn", "cn": "你想做的事情很多啊！", "pinyin": "Nǐ xiǎng zuò de shìqing hěn duō a!"}, {"speaker": "Bạch Gia Nguyệt", "cn": "是啊，你看，我还在网上买好颐和园的门票了呢。", "pinyin": "Shì a, nǐ kàn, wǒ hái zài wǎngshàng mǎihǎo Yíhéyuán de ménpiào le ne."}, {"speaker": "Lý Văn", "cn": "我的高中同学就在颐和园上班，可以让他给你好好介绍介绍。", "pinyin": "Wǒ de gāozhōng tóngxué jiù zài Yíhéyuán shàngbān, kěyǐ ràng tā gěi nǐ hǎohǎo jièshào jièshào."}], "translation_vn": "Bạch Gia Nguyệt: Thi xong rồi, bây giờ mình có thể đi du lịch nước ngoài được rồi. Lý Văn: Bạn định đi đâu? Bạch Gia Nguyệt: Mình muốn đi Bắc Kinh một lần nữa. Lý Văn: Tại sao vẫn đi Bắc Kinh? Bạch Gia Nguyệt: Vì mình muốn ăn vịt quay một lần nữa, uống trà sữa một lần nữa, đến Đại học Bắc Kinh xem phim một lần nữa. Lý Văn: Những việc bạn muốn làm nhiều thật đấy! Bạch Gia Nguyệt: Đúng vậy, bạn xem này, mình còn mua sẵn vé vào cổng Di Hoà Viên trên mạng rồi đấy nhé. Lý Văn: Bạn học thời phổ thông của mình đang làm việc ngay tại Di Hoà Viên, có thể bảo cậu ấy giới thiệu thật kĩ cho bạn.", "audio_dialogue": "15-3.mp3", "audio_vocab": "15-4.mp3"}, {"label": "Bài khóa 3", "type": "dialogue", "lines": [{"speaker": "Bạch Gia Nguyệt", "cn": "李文，你有一年没回国了吧？", "pinyin": "Lǐ Wén, nǐ yǒu yì nián méi huí guó le ba?"}, {"speaker": "Lý Văn", "cn": "不到一年。我六月的时候回去了一次。", "pinyin": "Bú dào yì nián. Wǒ Liùyuè de shíhou huíqù le yí cì."}, {"speaker": "Bạch Gia Nguyệt", "cn": "我怎么忘了？还是我送你去的机场呢。", "pinyin": "Wǒ zěnme wàng le? Hái shì wǒ sòng nǐ qù de jīchǎng ne."}, {"speaker": "Lý Văn", "cn": "是啊。", "pinyin": "Shì a."}, {"speaker": "Bạch Gia Nguyệt", "cn": "我记得你那次的机票很便宜。", "pinyin": "Wǒ jìde nǐ nà cì de jīpiào hěn piányi."}, {"speaker": "Lý Văn", "cn": "没错，可能因为那个时候去北京的人不多吧。", "pinyin": "Méi cuò, kěnéng yīnwèi nàge shíhou qù Běijīng de rén bù duō ba."}, {"speaker": "Bạch Gia Nguyệt", "cn": "这次的机票虽然有点儿贵，但想到就要飞北京了，我还是很高兴的。", "pinyin": "Zhè cì de jīpiào suīrán yǒudiǎnr guì, dàn xiǎngdào jiù yào fēi Běijīng le, wǒ hái shì hěn gāoxìng de."}], "translation_vn": "Bạch Gia Nguyệt: Lý Văn, bạn cũng cả năm rồi chưa về nước lần nào nhỉ? Lý Văn: Chưa đến một năm đâu. Hồi tháng Sáu mình có về một lần. Bạch Gia Nguyệt: Sao mình lại quên mất nhỉ? Chính là mình tiễn bạn ra sân bay mà. Lý Văn: Đúng rồi. Bạch Gia Nguyệt: Mình nhớ lần đó vé máy bay của bạn rẻ lắm. Lý Văn: Đúng vậy, chắc do dạo đó không có nhiều người đi Bắc Kinh chăng. Bạch Gia Nguyệt: Vé máy bay lần này tuy hơi đắt một chút, nhưng cứ nghĩ đến việc sắp được bay đến Bắc Kinh là mình vẫn thấy rất háo hức.", "audio_dialogue": "15-5.mp3", "audio_vocab": "15-6.mp3"}, {"label": "Bài khóa 4", "type": "passage", "lines": [{"speaker": "", "cn": "我六月的时候回过一次北京，现在有半年多没回去了，我有点儿想家。就要过年了，我要回国过年。家月这次也要去北京，我们都是星期五的飞机。家月说我们好像小鸟，一起飞到北京，再一起飞回这里。", "pinyin": "Wǒ Liùyuè de shíhou huíguo yí cì Běijīng, xiànzài yǒu bàn nián duō méi huíqù le, wǒ yǒudiǎnr xiǎng jiā. Jiù yào guònián le, wǒ yào huí guó guònián. Jiāyuè zhè cì yě yào qù Běijīng, wǒmen dōu shì Xīngqīwǔ de fēijī. Jiāyuè shuō wǒmen hǎoxiàng xiǎoniǎo, yìqǐ fēidào Běijīng, zài yìqǐ fēihuí zhèlǐ."}], "translation_vn": "Hồi tháng Sáu tôi từng về Bắc Kinh một lần, đến nay đã hơn nửa năm chưa về rồi, tôi thấy hơi nhớ nhà. Năm mới sắp đến rồi, tôi phải về nhà đón Tết thôi. Lần này Gia Nguyệt cũng đi về Bắc Kinh, chúng tôi đều đi chuyến bay ngày thứ Sáu. Gia Nguyệt nói chúng tôi giống như đôi chim nhỏ vậy, cùng nhau bay đến Bắc Kinh rồi lại cùng nhau bay trở về đây.", "audio_dialogue": "15-7.mp3", "audio_vocab": "15-8.mp3"}]}], "pos_table": [{"pos_cn": "名词", "pos_vn": "Danh từ", "abbr": "dt."}, {"pos_cn": "动词", "pos_vn": "Động từ", "abbr": "dgt."}, {"pos_cn": "形容词", "pos_vn": "Tính từ", "abbr": "tt."}, {"pos_cn": "代词", "pos_vn": "Đại từ", "abbr": "đt."}, {"pos_cn": "副词", "pos_vn": "Phó từ", "abbr": "phó."}, {"pos_cn": "介词", "pos_vn": "Giới từ", "abbr": "giới."}, {"pos_cn": "连词", "pos_vn": "Liên từ", "abbr": "liên."}, {"pos_cn": "助词", "pos_vn": "Trợ từ", "abbr": "trợ."}, {"pos_cn": "数词", "pos_vn": "Từ chỉ số đếm", "abbr": "số."}, {"pos_cn": "量词", "pos_vn": "Lượng từ", "abbr": "lượng."}, {"pos_cn": "数量词", "pos_vn": "Từ chỉ số lượng", "abbr": "sl."}, {"pos_cn": "叹词", "pos_vn": "Từ cảm thán", "abbr": "ct."}, {"pos_cn": "拟声词", "pos_vn": "Từ tượng thanh", "abbr": "tượng."}, {"pos_cn": "能愿动词", "pos_vn": "Động từ năng nguyện", "abbr": "đtnn."}, {"pos_cn": "前缀", "pos_vn": "Tiền tố", "abbr": "ttố."}, {"pos_cn": "后缀", "pos_vn": "Hậu tố", "abbr": "htố."}]};
